<template>
  <div
    ref="composerEl"
    class="chat-composer"
    :class="{
      'chat-composer--new-landing': isNewLanding,
      'chat-composer--collapsed': collapsed && promptAnnotations.length === 0 && selectedSkills.length === 0 && !hasContext,
      'chat-composer--floating': floating,
      'chat-composer--docked': !floating,
    }"
  >
    <div class="chat-composer-inner">
      <slot name="context" />
      <slot name="palette" />
      <div ref="inputPanelEl" class="chat-input-panel">
      <div v-if="attachments.length > 0 || localPaths.length > 0" class="chat-collapse-region">
        <div class="chat-attachments">
          <div
            v-for="(att, i) in attachments"
            :key="att.local_id"
            class="attachment-chip"
            :class="{ 'attachment-chip--busy': isAttachmentBusy(att), 'attachment-chip--failed': att.kind === 'failed' }"
            :data-mime="att.mime || ''"
            :title="attachmentTitle(att)"
          >
            <component
              :is="attachmentCanPreview(att) ? 'button' : 'span'"
              class="attachment-chip__primary"
              :class="{ 'attachment-chip__preview': attachmentCanPreview(att) }"
              :type="attachmentCanPreview(att) ? 'button' : undefined"
              :title="attachmentCanPreview(att) ? t('chat.openTitle', { title: att.name }) : undefined"
              :aria-label="attachmentCanPreview(att) ? t('chat.openTitle', { title: att.name }) : undefined"
              @click.stop="previewImage(att)"
            >
              <span class="attachment-chip__icon" aria-hidden="true">
                <span v-if="isAttachmentBusy(att)" class="spinner attachment-chip__spinner" />
                <Icon v-else-if="att.kind === 'failed'" name="info" :size="15" />
                <img v-else-if="isImageDisplayAttachment(att) && att.dataUrl" class="attachment-chip__thumb" :src="att.dataUrl" alt="" />
                <Icon v-else :name="attachmentIcon(att)" :size="15" />
              </span>
              <span class="attachment-chip__name">{{ att.name }}</span>
            </component>
            <span class="attachment-chip__meta">{{ attachmentMeta(att) }}</span>
            <button v-if="att.kind === 'failed' && att.file" class="attachment-action" :title="t('chat.retryUpload')" :aria-label="t('chat.retryUpload')" @click="emit('retryAttachment', i)">
              <Icon name="refresh" :size="12" />
            </button>
            <button class="attachment-action attachment-remove" :title="t('chat.remove')" :aria-label="t('chat.remove')" @click="emit('removeAttachment', i)">
              <Icon name="x" :size="12" />
            </button>
          </div>
          <div
            v-for="(path, i) in localPaths"
            :key="path"
            class="attachment-chip local-path-chip"
            :title="path"
          >
            <span class="attachment-chip__primary" :title="path" :aria-label="path" tabindex="0">
              <span class="attachment-chip__icon" aria-hidden="true"><Icon name="fileText" :size="15" /></span>
              <span class="attachment-chip__name">{{ path.split(/[\\/]/).pop() || path }}</span>
            </span>
            <button class="attachment-action attachment-remove" :title="t('chat.remove')" :aria-label="`${t('chat.remove')}: ${path}`" @click="emit('removeLocalPath', i)">
              <Icon name="x" :size="12" />
            </button>
          </div>
        </div>
      </div>
      <div v-if="promptAnnotations.length > 0" class="chat-collapse-region">
        <div
          class="chat-prompt-annotations"
          :aria-label="t('chat.promptAnnotations.draftLabel')"
          aria-live="polite"
          data-testid="composer-prompt-annotations"
        >
          <div class="chat-prompt-annotations__header" data-testid="composer-prompt-annotations-label">
            <Icon name="chat" :size="13" aria-hidden="true" />
            <span>{{ t('chat.promptAnnotations.label') }} · {{ promptAnnotations.length }}</span>
          </div>
          <div
            v-for="annotation in promptAnnotations"
            :key="annotation.annotationId"
            class="chat-prompt-annotation-chip"
            :class="{ 'is-stale': annotation.freshness === 'stale' }"
            :data-annotation-id="annotation.annotationId"
            role="group"
          >
            <span class="chat-prompt-annotation-chip__rail" aria-hidden="true" />
            <form
              v-if="editingAnnotationId === annotation.annotationId"
              class="chat-prompt-annotation-chip__editor"
              @submit.prevent="saveAnnotationEdit(annotation.annotationId)"
            >
              <input
                ref="annotationInputEl"
                v-model="annotationDraftBody"
                type="text"
                :maxlength="promptAnnotationMaxBodyLength"
                :aria-label="t('chat.promptAnnotations.editLabel')"
                @keydown.esc.prevent="cancelAnnotationEdit"
              />
              <button
                type="submit"
                :disabled="annotationDraftBody.trim().length === 0 || annotationDraftTooLong"
              >
                {{ t('common.save') }}
              </button>
              <button type="button" @click="cancelAnnotationEdit">
                {{ t('common.cancel') }}
              </button>
            </form>
            <template v-else>
              <button
                type="button"
                class="chat-prompt-annotation-chip__main"
                :title="annotation.body"
                @click="emit('jumpPromptAnnotation', annotation.annotationId)"
              >
                <span class="chat-prompt-annotation-chip__target">
                  {{ promptAnnotationTargetLabel(annotation, t) }}
                </span>
                <span class="chat-prompt-annotation-chip__text">
                  {{ annotation.body || t('chat.promptAnnotations.emptyDraft') }}
                </span>
                <span v-if="annotation.freshness === 'stale'" class="chat-prompt-annotation-chip__stale">
                  {{ t('workbench.annotationUnified.stale') }}
                </span>
              </button>
              <button
                type="button"
                class="attachment-action"
                :aria-label="t('chat.promptAnnotations.editLabel')"
                :title="t('chat.promptAnnotations.editLabel')"
                @click="beginAnnotationEdit(annotation)"
              >
                <Icon name="edit" :size="12" />
              </button>
              <button
                type="button"
                class="attachment-action attachment-remove"
                :aria-label="t('chat.promptAnnotations.removeLabel')"
                :title="t('chat.promptAnnotations.removeLabel')"
                @click="emit('discardPromptAnnotation', annotation.annotationId)"
              >
                <Icon name="x" :size="12" />
              </button>
            </template>
          </div>
        </div>
      </div>
        <div v-if="replanActive" class="chat-collapse-region">
          <div
            class="chat-replan-draft"
            role="status"
            aria-live="polite"
          >
            <span class="chat-replan-draft__icon" aria-hidden="true">
              <Icon name="pencil" :size="14" />
            </span>
            <span class="chat-replan-draft__copy">
              <strong>{{ t('chat.plan.revising') }}</strong>
              {{ t('chat.plan.reviseDraftHint') }}
            </span>
            <button
              type="button"
              class="chat-replan-draft__cancel"
              @click="emit('cancelReplan')"
            >
              {{ t('common.cancel') }}
            </button>
          </div>
        </div>
        <div class="chat-input-wrap">
          <ChatInlineEditor
            ref="inlineEditor"
            v-model="inputText"
            class="chat-textarea"
            :draft-key="draftKey"
            :selected-skills="selectedSkills"
            :skill-positions="skillPositions"
            :placeholder="placeholder"
            :disabled="inputDisabled"
            :aria-label="t('chat.messageToSend')"
            :aria-describedby="sendControlHint ? sendTooltipId : undefined"
            :aria-controls="paletteOpen ? paletteId || 'chat-slash-options' : undefined"
            :aria-expanded="paletteOpen"
            :aria-activedescendant="paletteOpen ? `${paletteId || 'chat-slash'}-option-${paletteActiveIndex}` : undefined"
            @beforeinput="emit('expand'); emit('beforeinput', $event)"
            @input="onTextareaInput"
            @keydown="emit('keydown', $event)"
            @composition-change="emit('compositionChange', $event)"
            @positions-change="emit('positionsChange', $event)"
            @remove-skill="emit('removeSkill', $event)"
            @pointerdown="emit('expand')"
            @focus="emit('expand')"
          />
        </div>
        <div class="chat-collapse-region chat-collapse-region--footer">
          <div ref="toolbarEl" class="chat-input-footer">
          <div class="chat-input-actions chat-input-actions--left">
            <div ref="addMenuAnchorEl" class="chat-settings-anchor chat-add-menu-anchor">
              <button
                class="btn btn--icon btn--ghost chat-plus-btn"
                :class="{ 'is-active': addMenuOpen }"
                :title="t('chat.add')"
                :aria-label="t('chat.add')"
                aria-haspopup="menu"
                :aria-expanded="addMenuOpen ? 'true' : 'false'"
                @click="toggleAddMenu"
              >
                <Icon name="plus" :size="18" />
              </button>
              <ChatComposerAddMenu
                v-if="addMenuOpen"
                :skills="skillPaletteItems"
                :composer-element="inputPanelEl"
                :skills-loading="skillsLoading"
                :skills-error="skillsError"
                :selected-skills="selectedSkills"
                :avoid-element="addMenuAvoidElement"
                :attachments-disabled="replanActive"
                :browser-use-available="browserUseAvailable === true"
                :local-paths-available="localPathsAvailable"
                :local-paths-disabled="replanActive || inputDisabled || localPathsBusy"
                :goal-mode-active="goalDraftArmed"
                :goal-mode-available="policy.goal && goalModeAvailable === true"
                :goal-mode-busy="goalModeBusy === true"
                :goal-mode-existing="goalModeExisting === true"
                :plan-mode-active="collaborationMode === 'plan'"
                :plan-mode-available="policy.plan && planModeAvailable === true"
                :plan-mode-busy="planModeBusy === true || planModeDisabled === true"
                :show-utility-actions="true"
                :voice-busy="voiceBusy"
                :voice-ready="voiceReady"
                :voice-recording="voiceRecording"
                :prompt-cache-keepalive-available="promptCacheKeepaliveAvailable"
                :prompt-cache-keepalive-session-ready="promptCacheKeepaliveSessionReady"
                :prompt-cache-keepalive-status="promptCacheKeepaliveStatus"
                @activate-goal-mode="policy.goal && emit('armGoal')"
                @activate-plan-mode="policy.plan && emit('setCollaborationMode', 'plan')"
                @attach-files="onAttachFiles"
                @select-browser-use="emit('selectBrowserUse')"
                @choose-skill="chooseMenuSkill"
                @retry-skills="emit('openAddMenu')"
                @reference-local-paths="chooseLocalFilePaths?.()"
                @voice-input="emit('voiceInput')"
                @voice-setup="emit('voiceSetup')"
                @export-markdown="emit('exportMarkdown')"
                @open-prompt-cache-keepalive="emit('openPromptCacheKeepalive')"
                @refresh-prompt-cache-keepalive="emit('refreshPromptCacheKeepalive')"
                @close="closeAddMenu"
              />
            </div>
            <div ref="runModeAnchorEl" class="chat-settings-anchor chat-run-mode-anchor">
              <button
                class="btn btn--ghost chat-run-mode-btn"
                :class="[`chat-run-mode-btn--${runMode}`, {
                  'is-active': runModeOpen,
                  'is-locked': runModeLocked,
                }]"
                :title="runModeLocked ? undefined : runModeLabel"
                :aria-label="`${t('chat.composer.runMode')}: ${runModeLabel}`"
                aria-haspopup="dialog"
                :aria-expanded="runModeOpen ? 'true' : 'false'"
                :aria-disabled="runModeLocked ? 'true' : 'false'"
                :aria-describedby="runModeLocked ? runModeLockTooltipId : undefined"
                :disabled="runModeLocked"
                @click="toggleRunMode"
              >
                <Icon name="shield" :size="16" aria-hidden="true" />
                <span class="chat-run-mode-btn__label">{{ runModeLabel }}</span>
              </button>
              <span
                v-if="runModeLocked"
                :id="runModeLockTooltipId"
                class="chat-run-mode-lock-tip"
                role="tooltip"
              >{{ runModeLockMessage }}</span>
              <ChatComposerRunMode
                v-if="runModeOpen"
                :run-mode="runMode"
                :allowed-run-modes="allowedRunModes"
                :safe-setup-available="safeSetupAvailable"
                @close="runModeOpen = false"
                @set-run-mode="emit('setRunMode', $event)"
              />
            </div>
            <div
              v-if="showProjectContext && projectWorkspace"
              class="chat-project-chip"
              :data-status="projectWorkspaceStatus || 'ready'"
              :title="projectWorkspace.path"
            >
              <Icon name="folder" :size="14" />
              <span class="chat-project-chip__name">{{ projectWorkspace.name }}</span>
              <span v-if="projectStatusMessage" class="chat-project-chip__status">
                {{ projectStatusMessage }}
              </span>
              <button
                v-if="canCloseProject"
                type="button"
                :disabled="projectBindingBusy"
                :aria-label="t('workspaces.closeProjectDraft')"
                :title="t('workspaces.closeProjectDraft')"
                @click="emit('closeProject')"
              >
                <Icon name="x" :size="12" />
              </button>
            </div>
            <button
              v-if="
                canChooseProject
                && isNewLanding
                && !projectWorkspace
                && (!projectWorkspaceStatus || projectWorkspaceStatus === 'none')
              "
              type="button"
              class="chat-project-choose"
              :aria-label="t('workspaces.chooseProject')"
              :title="t('workspaces.chooseProject')"
              :disabled="projectBindingBusy"
              @click="emit('chooseProject')"
            >
              <Icon name="folder" :size="15" />
              <span class="chat-project-choose__label">{{ t('workspaces.chooseProject') }}</span>
              <Icon class="chat-project-choose__chevron" name="chevronDown" :size="12" />
            </button>

            <ChatComposerGoalMode
              v-if="policy.goal"
              :active="goalDraftArmed"
              @disarm="emit('disarmGoal')"
            />
            <ChatComposerPlanMode
              v-if="policy.plan"
              :available="planModeAvailable === true"
              :mode="collaborationMode || 'default'"
              :busy="planModeBusy === true"
              :disabled="planModeDisabled === true"
              :applies-next-turn="planModeAppliesNextTurn === true"
              @set-mode="emit('setCollaborationMode', $event)"
            />
          </div>
          <div class="chat-input-actions chat-input-actions--right">
            <div
              v-if="modelRoutingVisible"
              ref="modelRoutingAnchorEl"
              class="chat-settings-anchor chat-model-routing-anchor"
            >
              <button
                class="chat-model-routing-btn"
                :class="[
                  `chat-model-routing-btn--${sessionRoutingMode}`,
                  { 'is-open': modelRoutingOpen },
                ]"
                :title="`${t('chat.modelRouting.title')}: ${modelRoutingTriggerLabel}${modelRoutingUsesDefault ? ` · ${t('chat.newTaskModel.defaultBadge')}` : ''}`"
                :aria-label="t('chat.modelRouting.title')"
                :aria-description="`${modelRoutingTriggerLabel}${modelRoutingUsesDefault ? ` · ${t('chat.newTaskModel.defaultBadge')}` : ''}`"
                :aria-expanded="modelRoutingOpen ? 'true' : 'false'"
                :aria-disabled="sessionRoutingControlBlocked ? 'true' : 'false'"
                @click="toggleModelRouting"
              >
                <Icon v-if="sessionRoutingMode === 'squilla_router'" name="router" :size="17" />
                <Icon v-else-if="sessionRoutingMode === 'llm_ensemble'" name="fork" :size="17" />
                <span v-else class="chat-model-routing-btn__dot" aria-hidden="true" />
                <span class="chat-model-routing-btn__label">{{ modelRoutingTriggerLabel }}</span>
                <span v-if="modelRoutingUsesDefault" class="chat-model-routing-btn__default">{{ t('chat.newTaskModel.defaultBadge') }}</span>
                <Icon class="chat-model-routing-btn__chevron" name="chevronDown" :size="12" />
                <span
                  v-if="showRouterNewBadge"
                  class="chat-model-routing-btn__new"
                  aria-hidden="true"
                >{{ t('chat.composer.badgeNew') }}</span>
              </button>
              <ChatComposerModelRouting
                v-if="modelRoutingOpen"
                ref="modelRoutingPanelRef"
                :anchor="modelRoutingAnchorEl"
                :model-routing-mode="sessionRoutingMode"
                :busy="sessionRoutingBusy || sessionRoutingControlBlocked"
                :routing-available="sessionRoutingAvailable"
                :is-new-task="isNewTask"
                :model-selection-available="modelSelectionAvailable"
                :available-models="availableModels"
                :model-selection="modelSelection"
                :default-model="defaultModel"
                :session-model-name="sessionModelName"
                :models-loading="modelsLoading"
                :models-error="modelsError"
                :model-provider-errors="modelProviderErrors"
                :model-selection-disabled-reason="modelSelectionDisabledReason"
                @close="closeModelRouting"
                @select-model="emit('selectModel', $event)"
                @refresh-models="emit('refreshModels')"
                @open-model-settings="openModelSettings"
                @set-session-routing-mode="emit('setSessionRoutingMode', $event)"
              />
            </div>

            <button
              v-if="showSkillQueueSend"
              type="button"
              class="btn btn--icon btn--danger chat-send-btn"
              :title="t('chat.stopResponseEsc')"
              :aria-label="t('chat.stopResponse')"
              @click="emit('stop')"
            >
              <Icon name="stop" :size="16" />
            </button>
            <span
              ref="sendControlEl"
              class="chat-send-control"
              :class="{ 'is-hint-dismissed': sendHintDismissed, 'is-hint-requested': sendHintRequested }"
              :tabindex="sendControlHint ? 0 : undefined"
              :role="sendControlHint ? 'group' : undefined"
              :aria-label="sendControlHint ? t('chat.send') : undefined"
              :aria-describedby="sendControlHint ? sendTooltipId : undefined"
              @mouseenter="sendHintDismissed = false"
              @focusin="sendHintDismissed = false"
              @pointerdown="focusSendHint"
              @keydown.esc="dismissSendHint"
            >
              <button
                v-if="(canStop || showStop) && !showSkillQueueSend"
                key="stop"
                class="btn btn--icon btn--danger chat-send-btn chat-stop-btn"
                :disabled="stopPending || !canStop"
                :aria-busy="stopPending || !canStop || undefined"
                :title="stopTargetsPlanRun
                  ? t('chat.planRun.stopExecutionEsc')
                  : t('chat.stopResponseEsc')"
                :aria-label="stopTargetsPlanRun
                  ? t('chat.planRun.stopExecution')
                  : t('chat.stopResponse')"
                @click="canStop && !stopPending && emit('stop')"
              >
                <Icon name="stop" :size="16" />
              </button>
              <button
                v-else
                key="send"
                class="btn btn--icon btn--primary chat-send-btn"
                :class="{ 'is-ready': hasSendContent && !sendBlockedMessage && !sendDisabled && !inputDisabled }"
                :title="sendBlockedMessage || sendPending || sendDisabled || sessionRoutingBusy || inputDisabled ? undefined
                  : showSkillQueueSend ? t('chat.sendQueues') : sendButtonTitle"
                :aria-label="replanActive ? t('chat.plan.reviseSend') : t('chat.send')"
                :aria-describedby="sendControlHint ? sendTooltipId : undefined"
                :aria-busy="sendPending || sessionRoutingBusy ? 'true' : 'false'"
                :disabled="sendPending || sendDisabled || Boolean(sendBlockedMessage) || sessionRoutingBusy || inputDisabled"
                @click="emit('send')"
              >
                <LoadingSpinner v-if="sendPending" />
                <Icon v-else name="arrowUp" :size="17" />
              </button>
              <span
                v-if="sendControlHint"
                :id="sendTooltipId"
                class="chat-send-tooltip"
                role="tooltip"
              >{{ sendControlHint }}</span>
            </span>
          </div>
          </div>
        </div>
      </div>
      <p v-if="isNewLanding" class="chat-ai-disclaimer" role="note">{{ t('chat.aiDisclaimer') }}</p>
    </div>
    <input
      ref="fileInputEl"
      type="file"
      multiple
      class="hidden"
      @change="emit('fileChange', $event)"
    />
  </div>
</template>

<script setup lang="ts">
import { useConversationPolicy } from '@/modules/conversationPolicy'
import type { SelectedSkillRef } from '@/types/selectedSkills'
import { computed, nextTick, onBeforeUnmount, ref, useId, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import Icon from '@/components/Icon.vue'
import { useComposerToolbarFit } from '@/composables/chat/useComposerToolbarFit'
import LoadingSpinner from '@/components/LoadingSpinner.vue'
import type { IconName } from '@/utils/icons'
import ChatComposerAddMenu from '@/components/chat/ChatComposerAddMenu.vue'
import ChatComposerGoalMode from '@/components/chat/ChatComposerGoalMode.vue'
import ChatInlineEditor from '@/components/chat/ChatInlineEditor.vue'
import type { ChatSlashCommand } from '@/composables/chat/useChatSlashCommands'
import ChatComposerModelRouting from '@/components/chat/ChatComposerModelRouting.vue'
import ChatComposerPlanMode from '@/components/chat/ChatComposerPlanMode.vue'
import ChatComposerRunMode from '@/components/chat/ChatComposerRunMode.vue'
import type { Attachment } from '@/types/chat'
import type { ModelDescriptor, ProviderListError } from '@/modules/providerConfiguration'
import { useDialogLayer } from '@/composables/useDialogA11y'
import { useDocumentEvent } from '@/composables/useDocumentEvent'
import type { ModelRoutingMode } from '@/types/modelRouting'
import type { SandboxRunMode } from '@/types/sandbox'
import type { CollaborationMode } from '@/types/plans'
import type { PromptAnnotation } from '@/types/promptAnnotations'
import type { PromptCacheKeepaliveStatus } from '@/types/promptCacheKeepalive'
import { promptAnnotationTargetLabel } from '@/utils/chat/promptAnnotationPresentation'
import {
  PROMPT_ANNOTATION_MAX_BODY_LENGTH,
  promptAnnotationBodyWithinLimit,
} from '@/types/promptAnnotations'
import { isAttachmentBusy, isImageDisplayAttachment } from '@/utils/chat/attachments'
import { fileTypeLabel } from '@/utils/fileType'

interface ChatComposerExpose {
  composerElement: () => HTMLElement | null
  canCollapse: () => boolean
  focusTextarea: (options?: { preserveFocus?: boolean }) => void
  isTextareaFocused: () => boolean
  resizeTextarea: () => void
  showSendBlockedHint: () => void
  editorElement: () => HTMLElement | null
  getSelection: () => { start: number; end: number; length: number }
  setSelectionRange: (start: number, end: number) => void
}

const props = withDefaults(defineProps<{
  /** Keep explicit message context visible when the floating input retracts. */
  hasContext?: boolean
  selectedSkills?: readonly SelectedSkillRef[]
  skillPositions?: Readonly<Record<string, number>>
  draftKey?: string
  skillPaletteItems?: ChatSlashCommand[]
  skillsLoading?: boolean
  skillsError?: string
  paletteOpen?: boolean
  paletteId?: string
  paletteActiveIndex?: number
  attachments: Attachment[]
  localPaths?: readonly string[]
  chooseAttachments?: () => Promise<boolean>
  chooseLocalFilePaths?: () => Promise<void>
  localPathsAvailable?: boolean
  localPathsBusy?: boolean
  busySendMode: 'queue' | 'steer'
  hasSendContent: boolean
  sendPending?: boolean
  sendDisabled?: boolean
  isStreaming: boolean
  canStop: boolean
  /** Retain the current task's shape during recovery; never grants Stop permission. */
  showStop?: boolean
  stopTargetsPlanRun?: boolean
  stopPending?: boolean
  isNewLanding: boolean
  placeholder: string
  sendButtonTitle: string
  sendBlockedMessage?: string
  showImageInputWarning?: boolean
  /** Opt in only when the blocking reason has no existing inline explanation. */
  showSendBlockedTooltip?: boolean
  inputDisabled?: boolean
  runMode: SandboxRunMode
  allowedRunModes: SandboxRunMode[]
  safeSetupAvailable?: boolean
  runModeLocked: boolean
  runModeLockMessage: string
  sessionRoutingMode: ModelRoutingMode
  sessionRoutingBusy: boolean
  sessionRoutingControlBlocked?: boolean
  sessionRoutingAvailable?: boolean
  isNewTask?: boolean
  modelSelectionAvailable?: boolean
  availableModels?: readonly ModelDescriptor[]
  modelSelection?: { model: string; provider: string | null } | null
  defaultModel?: { model: string; provider: string } | null
  sessionModelName?: string | null
  modelsLoading?: boolean
  modelsError?: string | null
  modelProviderErrors?: readonly ProviderListError[]
  modelSelectionDisabledReason?: 'routing' | 'busy' | 'unavailable' | null
  addMenuAvoidElement?: HTMLElement | null
  browserUseAvailable?: boolean
  goalDraftArmed?: boolean
  goalModeAvailable?: boolean
  goalModeBusy?: boolean
  goalModeExisting?: boolean
  voiceBusy: boolean
  voiceRecording: boolean
  voiceReady: boolean
  projectWorkspace?: { id: string; name: string; path: string } | null
  /** Settled presentation; sendBlockedMessage independently gates operations. */
  projectWorkspaceStatus?: 'none' | 'resolving' | 'ready' | 'unavailable' | 'removed' | 'unknown' | 'error'
  projectBindingBusy?: boolean
  projectStatusMessage?: string
  promptAnnotations?: readonly PromptAnnotation[]
  canCloseProject?: boolean
  canChooseProject?: boolean
  planModeAvailable?: boolean
  collaborationMode?: CollaborationMode
  planModeBusy?: boolean
  planModeDisabled?: boolean
  planModeAppliesNextTurn?: boolean
  replanActive?: boolean
  promptCacheKeepaliveAvailable?: boolean
  promptCacheKeepaliveSessionReady?: boolean
  promptCacheKeepaliveStatus?: PromptCacheKeepaliveStatus | null
  /** Collapsed to a single-line input (floating-composer retract). */
  collapsed?: boolean
  /** Floating-composer toggle: false docks the panel (solid surface, no
      glass) even though the composer still renders in the normal layout. */
  floating?: boolean
}>(), {
