const READY_TIMEOUT_MS = 7_000
const READ_TIMEOUT_MS = 7_000
const SNAPSHOT_TIMEOUT_MS = 3_000
const INITIAL_HISTORY_LIMIT = 100

interface SessionReadV4Transport {
  request<T = unknown>(
    method: string,
    params?: Record<string, unknown>,
    options?: RpcCallOptions,
  ): Promise<T>
  ready?(options?: {
    timeoutMs?: number
    signal?: AbortSignal
    timeoutAction?: 'reject' | 'reconnect'
    abortAction?: 'reject' | 'reconnect'
  }): Promise<void>
  readonly generation: number
  /** Explicit handshake bit; broad method probing alone is not sufficient to
   * opt legacy callers into the recovery lease protocol. */
  readonly sessionReadV2?: boolean
  supports?(method: string): boolean
  acknowledgeDelivery?(receipt: SnapshotDeliveryReceipt): Promise<void> | void
  resumeFlow?(receipt: SnapshotInstalledReceipt): Promise<void> | void
  recoveryVersion?(key: string): string
  snapshotInstalled?(key: string, version: string): void
  retireLane?(receipt: TransportLaneRetireReceipt): Promise<void> | void
  claimLaneOwner?(key: string, generation: number): TransportLaneOwner | undefined
  waitForConsumption?(key: string, cursor?: { streamGeneration: string; fromSeq: number; toSeq: number; replayAccepted?: boolean }): Promise<void>
  failProtocol?(generation: number): void
}

export interface SessionReadV4AdapterOptions {
  readonly concurrentHistoryReads?: () => boolean
  readonly now?: () => number
}

type MetadataWire = SessionsMessagesSubscribeResult | SessionsMessagesHydrateResult
type PendingUserInputsReadCursor = Pick<
  SessionsMessagesSubscribeResult,
  'stream_generation' | 'current_stream_seq'
>

interface SentLatch {
  readonly promise: Promise<number>
  sent(generation: number): void
  failed(error: unknown): void
}

interface OpenContext {
  readonly expectedGeneration: number
  readonly criticalRequestsQueued: Promise<void>
  readonly live: Promise<SessionReadPortLive>
  readonly metadata: Promise<SessionReadMetadata>
  readHistory(request: SessionReadPortHistoryRequest): Promise<SessionReadHistoryPage>
  retryMetadata(): Promise<SessionReadMetadata>
  reconcile(): Promise<SessionReadPortLive>
}

function sentLatch(): SentLatch {
  let settled = false
  let resolve!: (generation: number) => void
  let reject!: (error: unknown) => void
  const promise = new Promise<number>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise
    reject = rejectPromise
  })
  // A sibling critical-frame failure can make a later latch unreachable.
  // Observe it internally while retaining rejection semantics for awaiters.
  void promise.catch(() => {})
  return {
    promise,
    sent(generation) {
      if (settled) return
      settled = true
      resolve(generation)
    },
    failed(error) {
      if (settled) return
      settled = true
      reject(error)
    },
  }
}

function callOptions(
  signal: AbortSignal,
  timeoutMs: number,
  expectedGeneration: number,
  onSent?: (generation: number) => void,
  recoveryClass: RpcCallOptions['recoveryClass'] = 'mutation',
): RpcCallOptions {
  return {
    signal,
    timeoutMs,
    timeoutAction: 'reject',
    abortAction: 'reject',
    cancelOnAbort: true,
    expectedGeneration,
    recoveryClass,
    ...(onSent ? { onSent } : {}),
  }
}

function releaseOptions(expectedGeneration: number): RpcCallOptions {
  return {
    timeoutMs: READ_TIMEOUT_MS,
    timeoutAction: 'reject',
    abortAction: 'reject',
    expectedGeneration,
  }
}

function errorCode(error: unknown): string {
  if (!error || typeof error !== 'object') return ''
  const candidate = error as { code?: unknown; data?: { code?: unknown } }
  const code = candidate.code ?? candidate.data?.code
  return typeof code === 'string' ? code.toUpperCase() : ''
}

function isMissingMethod(error: unknown): boolean {
  return errorCode(error) === 'METHOD_NOT_FOUND'
}

function subscriptionError(error: unknown): unknown {
  return mapSessionReadError(error)
}

function snapshotInstallationHooks(
  staged: StagedSessionSnapshot | null,
  modern: SessionReadV2Lease | null = null,
): Pick<SessionReadPortLive, 'confirmInstalled' | 'assertInstalledCurrent'> {
  if (!staged && !modern) return {}
  // Keep each consumer bound to its exact snapshot. A later reconciliation
  // must not redirect an older confirmation to the replacement transfer.
  return {
    async confirmInstalled() {
      try {
        if (staged) await staged.confirmInstalled()
        if (modern) {
          const result = await modern.installConsumed(staged ? {
            sessionId: staged.sessionId,
            sessionEpoch: staged.sessionEpoch,
            streamGeneration: staged.value.stream_generation,
            streamSeq: staged.value.current_stream_seq,
          } : undefined)
          if (result.status !== 'installed') {
            throw new SessionReadFailure('busy', 'Session replay is still catching up.', true)
          }
        }
      } catch (error) {
        throw mapSessionReadError(error)
      }
    },
    assertInstalledCurrent() {
      if (staged) {
        try {
          staged.assertInstalledCurrent()
        } catch (error) {
          throw mapSessionReadError(error)
        }
      }
    },
  }
}

function invalidContract(method: string): SessionReadContractError {
  return new SessionReadContractError(`${method} violated its generated v4 Contract.`)
}

function requireParams(
  method: string,
  params: object,
  validate: (value: unknown) => boolean,
): void {
  if (!validate(params)) throw invalidContract(`${method} params`)
}

function requireResult<T>(
  method: string,
  result: unknown,
  validate: (value: unknown) => boolean,
): T {
  if (!validate(result)) throw invalidContract(`${method} result`)
  return result as T
}

function abortError(message = 'Session read lease is closed.'): Error {
  const error = new Error(message)
  error.name = 'AbortError'
  return error
}

function objectValue(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null
}

function canonicalSessionMetadata(value: unknown): unknown {
  const result = objectValue(value)
  const lock = objectValue(result?.run_mode_lock)
  // Protocol 3 encodes Safe as "trusted". Decode only that wire alias;
  // all other fields and invalid values still go through strict validation.
  if (!result || lock?.runMode !== 'trusted') return value
  return { ...result, run_mode_lock: { ...lock, runMode: 'safe' } }
}

function projectJson(value: unknown): unknown {
  if (Array.isArray(value)) return Object.freeze(value.map(projectJson))
  const item = objectValue(value)
  if (!item) return value
  return Object.freeze(Object.fromEntries(
    Object.entries(item).map(([key, child]) => [key, projectJson(child)]),
  ))
}

function projectObject(value: unknown): SessionReadJsonObject | null {
  const item = objectValue(value)
  return item ? projectJson(item) as SessionReadJsonObject : null
}

function projectObjectArray(value: unknown): readonly SessionReadJsonObject[] {
  if (!Array.isArray(value)) return Object.freeze([])
  return Object.freeze(value.flatMap(item => {
    const projected = projectObject(item)
    return projected ? [projected] : []
  }))
}

function additionalFields(
  value: Record<string, unknown>,
  known: ReadonlySet<string>,
): SessionReadJsonObject {
  return Object.freeze(Object.fromEntries(
    Object.entries(value)
      .filter(([key]) => !known.has(key))
      .map(([key, child]) => [key, projectJson(child)]),
  ))
}

function textValue(...values: unknown[]): string | null {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim()
    if (typeof value === 'number' && Number.isFinite(value)) return String(value)
  }
  return null
}

function numberValue(...values: unknown[]): number | null {
  for (const value of values) {
    if (typeof value === 'number' && Number.isFinite(value)) return value
  }
  return null
}

const METADATA_FIELDS = new Set([
  'key',
  'workspaceId',
  'projectWorkspace',
  'projectWorkspaceDeferred',
  'active_task_group_ids',
  'run_mode_lock',
  'pendingUserInputs',
  'collaboration',
  'routing',
  'planPresentations',
  'currentPlan',
  'activePlanRun',
  'goal',
  'goalSnapshotStreamSeq',
  'tasks',
  'active_task',
  'last_task',
  'run_status',
  'queued_task_ids',
  'epoch',
  'hydration_complete',
  'deferred_fields',
  'subscribed',
  'stream_generation',
  'current_stream_seq',
  'replay_complete',
  'replay_gap_reason',
  'replayed_count',
])

function projectMetadata(
  value: MetadataWire,
  readCursor?: PendingUserInputsReadCursor,
): SessionReadMetadata {
  const lock = value.run_mode_lock
  const raw = value as unknown as Record<string, unknown>
  const rawLock = lock as unknown as Record<string, unknown>
  return Object.freeze({
    sessionKey: value.key,
    workspaceId: value.workspaceId,
    projectWorkspace: projectObject(value.projectWorkspace),
    projectWorkspaceDeferred: value.projectWorkspaceDeferred,
    activeTaskGroupIds: Object.freeze([...value.active_task_group_ids]),
    runModeLock: Object.freeze({
      locked: lock.locked,
      runMode: lock.runMode === 'safe' || lock.runMode === 'full' ? lock.runMode : null,
      source: textValue(lock.source),
      additional: additionalFields(rawLock, new Set(['locked', 'runMode', 'source'])),
    }),
    pendingUserInputs: projectObjectArray(value.pendingUserInputs),
    collaboration: projectObject(value.collaboration),
    routing: projectObject(value.routing),
    planPresentations: projectObjectArray(value.planPresentations),
    currentPlan: projectObject(value.currentPlan),
    activePlanRun: projectObject(value.activePlanRun),
    goal: projectObject(value.goal),
    goalSnapshotStreamSeq: numberValue(value.goalSnapshotStreamSeq),
    tasks: projectObjectArray(value.tasks),
    activeTask: projectObject(value.active_task),
    lastTask: projectObject(value.last_task),
    runStatus: value.run_status,
    queuedTaskIds: Object.freeze([...(value.queued_task_ids ?? [])]),
    epoch: numberValue(value.epoch),
    pendingUserInputsCursor: Object.freeze({
      streamGeneration: textValue(raw.stream_generation) ?? readCursor?.stream_generation ?? null,
      currentStreamSeq: numberValue(raw.current_stream_seq) ?? readCursor?.current_stream_seq ?? null,
    }),
    hydrationComplete: value.hydration_complete,
    deferredFields: Object.freeze([...value.deferred_fields]),
    additional: additionalFields(raw, METADATA_FIELDS),
  })
}

function activeTaskId(value: MetadataWire): string | null {
  const task = objectValue(value.active_task)
  return textValue(task?.task_id, task?.taskId, task?.id)
}

function activity(
  value: MetadataWire,
  snapshot: SessionsMessagesSnapshotResult | null,
): SessionReadActivity {
  if (snapshot?.task_id) return 'foreground'
  const status = value.run_status.trim().toLowerCase()
  if (status === 'queued' || status === 'running' || status === 'approval_pending') {
    return 'foreground'
  }
  if (value.active_task_group_ids.length > 0) return 'background'
  if (status === 'idle' || status === 'completed' || status === 'succeeded') return 'idle'
  return 'unknown'
}

function projectSnapshot(value: SessionsMessagesSnapshotResult): SessionReadSnapshot {
  return Object.freeze({
    sessionKey: value.key,
    taskId: value.task_id,
    streamGeneration: value.stream_generation,
    currentStreamSeq: value.current_stream_seq,
    events: Object.freeze(value.events.flatMap(event => {
      const projected = projectConversationSnapshotEvent(event.event, projectObject(event.payload))
      return projected ? [Object.freeze({ ...projected, payload: Object.freeze(projected.payload) })] : []
    })),
  })
}

async function hydrate(
  rpc: SessionReadV4Transport,
  sessionKey: string,
  signal: AbortSignal,
  expectedGeneration: number,
  readCursor: PendingUserInputsReadCursor,
): Promise<SessionReadMetadata> {
  const params: SessionsMessagesHydrateParams = { key: sessionKey }
  requireParams(SESSIONS_MESSAGES_HYDRATE_METHOD, params, validateSessionsMessagesHydrateParams)
  let raw: unknown
  try {
    raw = await rpc.request(
      SESSIONS_MESSAGES_HYDRATE_METHOD,
      params,
      callOptions(signal, READ_TIMEOUT_MS, expectedGeneration, undefined, 'safe-read'),
    )
  } catch (error) {
    throw mapSessionReadError(error)
  }
  const result = requireResult<SessionsMessagesHydrateResult>(
    SESSIONS_MESSAGES_HYDRATE_METHOD,
    canonicalSessionMetadata(raw),
    validateSessionsMessagesHydrateResult,
  )
  if (result.key !== sessionKey) throw invalidContract(SESSIONS_MESSAGES_HYDRATE_METHOD)
  // Hydration does not carry its own cursor. A preceding confirmed read is
  // a lower bound, so a delayed empty snapshot cannot erase a newer live input.
  return projectMetadata(result, readCursor)
}

async function optionalSnapshot(
  rpc: SessionReadV4Transport,
  params: SessionsMessagesSnapshotParams,
  signal: AbortSignal,
  expectedGeneration: number,
  latch: SentLatch,
): Promise<SessionsMessagesSnapshotResult | null> {
  let sentGeneration: number | null = null
  try {
    const raw = await rpc.request(
      SESSIONS_MESSAGES_SNAPSHOT_METHOD,
      params,
      callOptions(signal, SNAPSHOT_TIMEOUT_MS, expectedGeneration, generation => {
        sentGeneration = generation
        latch.sent(generation)
      }, 'safe-read'),
    )
    return requireResult<SessionsMessagesSnapshotResult>(
      SESSIONS_MESSAGES_SNAPSHOT_METHOD,
      raw,
      validateSessionsMessagesSnapshotResult,
    )
  } catch (error) {
    if (isMissingMethod(error)) {
      // A pre-capability Gateway can reject before onSent. Treat only this
      // capability miss as a terminally absent snapshot frame.
      latch.sent(expectedGeneration)
      return null
    }
    const projected = mapSessionReadError(error)
    if (
      projected instanceof SessionReadFailure
      && projected.kind === 'timeout'
      && sentGeneration === expectedGeneration
      && rpc.generation === expectedGeneration
      && !signal.aborted
    ) {
      // A sent snapshot can miss its own deadline without invalidating the
      // independently acknowledged live subscription or its replay cursor.
      return null
    }
    latch.failed(projected)
    throw projected
  }
}

function assertFrameGeneration(expected: number, generations: readonly number[]): void {
  if (generations.some(generation => generation !== expected)) {
    throw new SessionReadContractError(
      'Session read critical requests crossed a connection generation.',
    )
  }
}

/**
 * Generated-contract Adapter. It owns wire validation/projection, connection
 * admission, frame order and generation-pinned release; no generated type
 * crosses SessionReadPort.
 */
export function createV4SessionReadPort(
  rpc: SessionReadV4Transport,
  options: SessionReadV4AdapterOptions = {},
): SessionReadPort {
  const owners = new Map<string, object>()
  const historyPolicy: SessionHistoryV4Policy = {
    concurrentHistoryReads: options.concurrentHistoryReads ?? (() => true),
    ...(options.now ? { now: options.now } : {}),
  }
  return Object.freeze({
    open(request: SessionReadPortOpenRequest): SessionReadPortLease {
      let closed = false
      const owner = {}
      owners.set(request.sessionKey, owner)
      let transfer: SessionSnapshotTransfer | null = null
      let terminalSnapshotError: unknown = null
      let subscribedGeneration: number | null = null
      let laneOwner: TransportLaneOwner | undefined
      let v2Lease: SessionReadV2Lease | null = null
      let v2BaseApplied = false
      const v2Controller = new AbortController()
      const abortV2 = () => v2Controller.abort()
      request.signal.addEventListener('abort', abortV2, { once: true })

      async function createContext(): Promise<OpenContext> {
        const admissionDeadline = performance.now() + READ_TIMEOUT_MS
        await rpc.ready?.({
          timeoutMs: READY_TIMEOUT_MS,
          signal: request.signal,
          timeoutAction: 'reject',
          abortAction: 'reject',
        })
        if (closed || request.signal.aborted) {
          throw abortError('Session read closed before connection admission.')
        }
        const expectedGeneration = rpc.generation
        // A local draft needs live admission before its first send, but has no
        // durable identity for read-v2 until that send has been accepted.
        const v2Enabled = !request.provisionalDraft
          && rpc.sessionReadV2 === true && supportsSessionReadV2(rpc)
        const subscribeParams: SessionsMessagesSubscribeParams = {
          key: request.sessionKey,
          since_stream_generation: request.resumeFrom.streamGeneration,
          since_stream_seq: request.resumeFrom.streamSeq,
          fast_ack: true,
        }
        const snapshotParams: SessionsMessagesSnapshotParams = { key: request.sessionKey }
        requireParams(
          SESSIONS_MESSAGES_SUBSCRIBE_METHOD,
          subscribeParams,
          validateSessionsMessagesSubscribeParams,
        )
        requireParams(
          SESSIONS_MESSAGES_SNAPSHOT_METHOD,
          snapshotParams,
          validateSessionsMessagesSnapshotParams,
        )

        const subscribeSent = sentLatch()
        const snapshotSent = sentLatch()
        let stagedSnapshot: StagedSessionSnapshot | null = null
        async function readSnapshot(latch: SentLatch): Promise<SessionsMessagesSnapshotResult | null> {
          if (!rpc.supports?.(SESSIONS_MESSAGES_SNAPSHOT_READ_METHOD)) {
            return optionalSnapshot(rpc, snapshotParams, request.signal, expectedGeneration, latch)
          }
          if (transfer?.budgetExhausted) terminalSnapshotError = new SessionReadFailure(
            'budget-exhausted', 'Snapshot recovery budget exhausted. Retry explicitly or use paginated history.', false,
          )
          if (terminalSnapshotError) throw terminalSnapshotError
          try {
            if (!transfer || transfer.retired || transfer.installed) {
              transfer?.release()
              transfer = createV4SessionSnapshotTransfer(rpc, request.sessionKey, request.signal, expectedGeneration)
            }
            const staged = await transfer.read(latch.sent)
            stagedSnapshot = staged
            return staged.value
          } catch (error) {
            latch.failed(error)
            const projected = mapSessionReadError(error)
            if (projected instanceof SessionReadFailure && !projected.retryable
              && projected.kind !== 'aborted') {
              terminalSnapshotError = projected
              transfer?.release()
            }
            throw projected
          }
        }
        function assertSnapshotIdentity(metadata: SessionReadMetadata) {
          if (!stagedSnapshot) return
          const sessionId = textValue(metadata.additional.session_id, metadata.additional.sessionId)
          if ((metadata.epoch !== null && metadata.epoch !== stagedSnapshot.sessionEpoch)
            || (sessionId !== null && sessionId !== stagedSnapshot.sessionId)) {
            throw new SessionReadContractError('Session snapshot identity changed during reconciliation.')
          }
        }
        let acknowledgedSubscription: SessionsMessagesSubscribeResult | null = null
        let admission: Promise<SessionsMessagesSubscribeResult> | null = null
        function assertAdmissionCurrent() {
          if (closed || request.signal.aborted || rpc.generation !== expectedGeneration
            || owners.get(request.sessionKey) !== owner) throw abortError()
        }
        function fenceRebaseFailure(error: unknown): unknown {
          const code = errorCode(error)
          if (code === 'REBASE_REQUIRED' || code === 'READ_STALE'
            || (error instanceof SessionReadFailure && error.kind === 'rebase-required')) {
            try { assertAdmissionCurrent() } catch (obsolete) { return obsolete }
          }
          return error
        }
        function ensureAdmission(initial = false): Promise<SessionsMessagesSubscribeResult> {
          if (admission) return admission
          const current = (async () => {
            assertAdmissionCurrent()
            if (!acknowledgedSubscription) {
              const raw = await rpc.request(
                SESSIONS_MESSAGES_SUBSCRIBE_METHOD,
                subscribeParams,
                callOptions(
                  request.signal,
                  initial ? Math.max(1, admissionDeadline - performance.now()) : READ_TIMEOUT_MS,
                  expectedGeneration,
                  generation => {
                    if (subscribedGeneration !== generation || !laneOwner) {
                      laneOwner = rpc.claimLaneOwner?.(request.sessionKey, generation)
                    }
                    subscribedGeneration = generation
                    subscribeSent.sent(generation)
                  },
                ),
              )
              assertAdmissionCurrent()
              const result = requireResult<SessionsMessagesSubscribeResult>(
                SESSIONS_MESSAGES_SUBSCRIBE_METHOD, canonicalSessionMetadata(raw),
                validateSessionsMessagesSubscribeResult,
              )
              if (result.key !== request.sessionKey || !result.subscribed) {
                throw invalidContract(SESSIONS_MESSAGES_SUBSCRIBE_METHOD)
              }
              acknowledgedSubscription = result
            }
            if (v2Enabled && !v2BaseApplied) {
              if (!v2Lease) {
                const modern = await openV2SessionRead(rpc, request.sessionKey, expectedGeneration, v2Controller.signal)
                try {
                  assertAdmissionCurrent()
                } catch (error) {
                  // This releases only the obsolete consumer. A same-key view
                  // may retain its own handle to the shared physical lease.
                  await modern.close()
                  throw error
                }
                // Own the lease before base installation can fail or cancel.
                v2Lease = modern
              }
              const modern = v2Lease
              const advertisedEpoch = numberValue(acknowledgedSubscription.epoch)
              if (advertisedEpoch !== null && advertisedEpoch !== modern.sessionEpoch) {
                throw new SessionReadContractError('Session read v2 identity changed during subscribe.')
              }
              const base = await modern.install({ baseApplied: true })
              assertAdmissionCurrent()
              if (base.status !== 'base_applied' && base.status !== 'catching_up' && base.status !== 'installed') {
                throw new SessionReadFailure('busy', 'Session replay base is not available yet.', true)
              }
              v2BaseApplied = true
            }
            return acknowledgedSubscription
          })().catch(error => {
            throw subscriptionError(fenceRebaseFailure(error))
          })
          const observed = current.finally(() => {
            if (admission === observed) admission = null
          })
          admission = observed
          return observed
        }
        const subscribePromise = ensureAdmission(true).catch(error => {
          subscribeSent.failed(error)
          throw error
        })
        const snapshotPromise = subscribeSent.promise.then(() => readSnapshot(snapshotSent)).then(result => {
          if (result && result.key !== request.sessionKey) {
            throw invalidContract(SESSIONS_MESSAGES_SNAPSHOT_METHOD)
          }
          return result
        })

        const liveFramesQueued = Promise.all([
          subscribeSent.promise,
          snapshotSent.promise,
        ]).then(generations => {
          assertFrameGeneration(expectedGeneration, generations)
        })

        const historySent = request.includeInitialHistory ? sentLatch() : null
        const initialHistory = historySent
          ? (v2Enabled ? Promise.all([liveFramesQueued, subscribePromise]) : liveFramesQueued).then(() => v2Enabled
            ? requestV2SessionHistory(rpc, request.sessionKey, {
                direction: 'latest', limit: INITIAL_HISTORY_LIMIT, signal: request.signal,
              }, expectedGeneration, historySent.sent).then(result => {
                historySent.sent(expectedGeneration)
                return result
              })
            : requestV4SessionHistory(
                rpc,
                request.sessionKey,
                {
                  direction: 'latest',
                  limit: INITIAL_HISTORY_LIMIT,
                  signal: request.signal,
                },
                {
                  includeSummaries: true,
                  expectedGeneration,
                  onSent: historySent.sent,
                  policy: historyPolicy,
                  contractError: invalidContract,
                },
              )).catch(error => {
              historySent.failed(error)
              throw error
            })
          : null
        // Eager history may finish before a consumer asks for it. Observe the
        // rejection here while preserving it for the first latest() call.
        void initialHistory?.catch(() => {})

        const criticalRequestsQueued = liveFramesQueued.then(async () => {
          if (!historySent) return
          const historyGeneration = await historySent.promise
          assertFrameGeneration(expectedGeneration, [historyGeneration])
        })

        const live = Promise.all([
          subscribePromise,
          snapshotPromise,
          criticalRequestsQueued,
        ]).then(([subscription, snapshot]) => {
          assertSnapshotIdentity(projectMetadata(subscription))
          return Object.freeze({
          sessionKey: request.sessionKey,
          activity: activity(subscription, snapshot),
          activeTaskId: snapshot?.task_id ?? activeTaskId(subscription),
          initialMetadata: projectMetadata(subscription),
          snapshot: snapshot ? projectSnapshot(snapshot) : null,
          ...snapshotInstallationHooks(stagedSnapshot, v2Lease),
          cursor: Object.freeze({
            sessionKey: request.sessionKey,
            sessionEpoch: subscription.epoch,
            streamGeneration: subscription.stream_generation,
            currentStreamSeq: subscription.current_stream_seq,
            replayComplete: subscription.replay_complete,
            replayGapReason: subscription.replay_gap_reason,
          }),
          snapshotCursor: snapshot
            ? Object.freeze({
                sessionKey: request.sessionKey,
                sessionEpoch: subscription.epoch,
                streamGeneration: snapshot.stream_generation,
                currentStreamSeq: snapshot.current_stream_seq,
              })
            : null,
        } satisfies SessionReadPortLive)
        })
        void live.catch(() => {})

        const metadata = subscribePromise.then(subscription => {
          if (subscription.hydration_complete) return projectMetadata(subscription)
          return criticalRequestsQueued.then(() => hydrate(
            rpc,
            request.sessionKey,
            request.signal,
            expectedGeneration,
            subscription,
          ))
        })
        void metadata.catch(() => {})
        void criticalRequestsQueued.catch(() => {})

        let initialHistoryAvailable = initialHistory !== null
        let retry: Promise<SessionReadMetadata> | null = null
        let reconciliation: Promise<SessionReadPortLive> | null = null

        function reconcile(): Promise<SessionReadPortLive> {
          if (closed || request.signal.aborted) return Promise.reject(abortError())
          if (reconciliation) return reconciliation
          const current = (async (): Promise<SessionReadPortLive> => {
            if (rpc.generation !== expectedGeneration) throw abortError('The connection generation changed.')
            const subscription = await ensureAdmission()
            const snapshot = await readSnapshot(sentLatch())
            if (snapshot && snapshot.key !== request.sessionKey) {
              throw invalidContract(SESSIONS_MESSAGES_SNAPSHOT_METHOD)
            }
            // The completed snapshot precedes this hydration and is its latest
            // known lower bound. Reusing only the initial subscribe cursor could
            // keep old questions actionable forever after a missed terminal.
            // Legacy Gateways without snapshots retain the conservative bound.
            const metadata = supportsSnapshotRecovery(rpc)
              ? Object.freeze({ ...projectMetadata(subscription), hydrationComplete: false })
              : await hydrate(rpc, request.sessionKey, request.signal, expectedGeneration, snapshot ?? subscription)
            assertSnapshotIdentity(metadata)
            // A staged snapshot must be applied by the domain and confirmed
            // before its watermark can prove read-v2 consumption. Its hook
            // performs the final installation after that consumer step.
            if (v2Lease && !stagedSnapshot) {
              const install = await v2Lease.installConsumed()
              if (install.status !== 'installed') {
                throw new SessionReadFailure('busy', 'Session replay is still catching up.', true)
              }
            }
            if (closed || request.signal.aborted || rpc.generation !== expectedGeneration) throw abortError()
            initialHistoryAvailable = false
            return Object.freeze({
              sessionKey: request.sessionKey,
              activity: activity({ ...subscription, run_status: metadata.runStatus,
                active_task_group_ids: [...metadata.activeTaskGroupIds] } as MetadataWire, snapshot),
              activeTaskId: snapshot?.task_id ?? textValue(metadata.activeTask?.task_id, metadata.activeTask?.taskId),
              initialMetadata: metadata,
              snapshot: snapshot ? projectSnapshot(snapshot) : null,
              ...snapshotInstallationHooks(stagedSnapshot, v2Lease),
              cursor: Object.freeze({
                sessionKey: request.sessionKey,
                sessionEpoch: metadata.epoch,
                streamGeneration: snapshot?.stream_generation ?? subscription.stream_generation,
                currentStreamSeq: snapshot?.current_stream_seq ?? subscription.current_stream_seq,
                replayComplete: true,
              }),
              snapshotCursor: snapshot ? Object.freeze({
                sessionKey: request.sessionKey,
                sessionEpoch: metadata.epoch,
                streamGeneration: snapshot.stream_generation,
                currentStreamSeq: snapshot.current_stream_seq,
              }) : null,
            })
          })().catch(error => {
            throw mapSessionReadError(fenceRebaseFailure(error))
          })
          const observed = current.finally(() => {
            if (reconciliation === observed) reconciliation = null
          })
          reconciliation = observed
          return observed
        }

        async function readHistory(
          historyRequest: SessionReadPortHistoryRequest,
        ): Promise<SessionReadHistoryPage> {
          if (closed || historyRequest.signal.aborted) throw abortError()
          if (historyRequest.direction !== 'latest' && !historyRequest.cursor.trim()) {
            throw new TypeError(`${historyRequest.direction} session history requires a cursor.`)
          }
          if (
            historyRequest.direction === 'latest'
            && historyRequest.limit === INITIAL_HISTORY_LIMIT
            && initialHistoryAvailable
            && initialHistory
          ) {
            initialHistoryAvailable = false
            return initialHistory
          }
          if (v2Enabled) {
            await ensureAdmission()
            return requestV2SessionHistory(rpc, request.sessionKey, historyRequest, expectedGeneration)
          }
          return requestV4SessionHistory(
            rpc,
            request.sessionKey,
            historyRequest,
            {
              includeSummaries: true,
              expectedGeneration,
              policy: historyPolicy,
              contractError: invalidContract,
            },
          )
        }

        function retryMetadata(): Promise<SessionReadMetadata> {
          if (closed || request.signal.aborted) return Promise.reject(abortError())
          if (retry) return retry
          const current = (async () => {
            const subscription = await ensureAdmission()
            if (!v2Enabled) await criticalRequestsQueued
            return hydrate(
              rpc,
              request.sessionKey,
              request.signal,
              expectedGeneration,
              subscription,
            )
          })()
          const observed = current.finally(() => {
            if (retry === observed) retry = null
          })
          retry = observed
          void retry.catch(() => {})
          return retry
        }

        return {
          expectedGeneration,
          criticalRequestsQueued,
          live,
          metadata,
          readHistory,
          retryMetadata,
          reconcile,
        }
      }
      let setup: Promise<OpenContext> | null = null
      function acquireContext(): Promise<OpenContext> {
        if (closed || request.signal.aborted) return Promise.reject(abortError())
        if (setup) return setup
        const pending = createContext().catch(error => { throw mapSessionReadError(error) })
        setup = pending
        // A failed ready/admission attempt has not established a subscription.
        // Keep its original consumers failed, but let the next explicit retry
        // acquire one fresh context instead of replaying a rejected promise.
        void pending.catch(error => {
          if (setup === pending && error instanceof SessionReadFailure && error.retryable) {
            setup = null
          }
        })
        return pending
      }
      const initialSetup = acquireContext()

      const historyRead = (historyRequest: SessionReadPortHistoryRequest) => acquireContext().then(
        context => context.readHistory(historyRequest),
      ).catch(error => { throw mapSessionReadError(error) })

      async function close(): Promise<void> {
        if (closed) return
        closed = true
        v2Controller.abort()
        request.signal.removeEventListener('abort', abortV2)
        transfer?.release()
        // No await before the ownership/send decision: a pending ready wait
        // cannot later send subscribe after this local close.
        if (owners.get(request.sessionKey) !== owner) return
        owners.delete(request.sessionKey)
        const generation = subscribedGeneration
        if (generation === null || rpc.generation !== generation) return
        // Fence the departing consumer synchronously, before read-close or
        // unsubscribe can yield. The server's retire receipt still owns credit.
        const departingLane = laneOwner
        departingLane?.beginRetirement()
        const modern = v2Lease
        v2Lease = null
        const cleanup: Promise<unknown>[] = []
        if (modern) {
          try { cleanup.push(modern.close()) } catch (error) { cleanup.push(Promise.reject(error)) }
        }
        const params: SessionsMessagesUnsubscribeParams = { key: request.sessionKey }
        const sent = sentLatch()
        try {
          requireParams(SESSIONS_MESSAGES_UNSUBSCRIBE_METHOD, params, validateSessionsMessagesUnsubscribeParams)
          const result = rpc.request(SESSIONS_MESSAGES_UNSUBSCRIBE_METHOD, params, {
            ...releaseOptions(generation), onSent: sent.sent,
          })
          void result.then(value => {
            // In-memory ports may not implement onSent. A completed response
            // also proves that its frame was admitted.
            const retireResult = requireResult<SessionsMessagesUnsubscribeResult>(
              SESSIONS_MESSAGES_UNSUBSCRIBE_METHOD, value, validateSessionsMessagesUnsubscribeResult,
            )
            const retire = retireResult?.lane_retire
            if (departingLane) {
              void departingLane.completeRetirement(retire ?? null).catch(() => {})
            } else if (retire && rpc.retireLane) {
              void Promise.resolve(rpc.retireLane(retire)).catch(() => {})
            }
            sent.sent(generation)
          }).catch(error => {
            departingLane?.failRetirement()
            sent.failed(error)
          })
          cleanup.push(sent.promise)
        } catch (error) {
          departingLane?.failRetirement()
          cleanup.push(Promise.reject(error))
        }
        // Both generation-pinned cleanup requests have started before yielding.
        // A failed read-close must not suppress unsubscribe or its retire fence.
        const results = await Promise.allSettled(cleanup)
        for (const result of results) {
          if (result.status === 'rejected' && !isMissingMethod(result.reason)) throw result.reason
        }
      }

      return Object.freeze({
        criticalRequestsQueued: initialSetup.then(context => context.criticalRequestsQueued),
        live: initialSetup.then(context => context.live),
        metadata: initialSetup.then(context => context.metadata),
        readHistory: historyRead,
        retryMetadata: () => acquireContext().then(context => context.retryMetadata()),
        reconcile: () => acquireContext().then(context => context.reconcile()),
        close,
      })
    },
  })
}
