    && sessionKey.value
  ) {
    try {
      const snapshot = await workbenchResourcesStore.load(resourceSessionKey)
      if (chatViewDisposed || sessionKey.value !== resourceSessionKey || workbenchOwnerKey.value !== visibleOwnerKey) return
      const resources = workbenchResourcesStore.navigationResources(resourceSessionKey)
      if (snapshot.available && resources.length > 0) {
        const item = createResourceCollectionWorkbenchItem({
          resources,
          sessionKey: resourceSessionKey,
          title: t('workbench.resources.title'),
        })
        item.scope = { type: 'session', id: visibleOwnerKey }
        openWorkbenchItemExplicit(item)
        return
      }
    } catch {
      // Mixed-version or reconnect fallback keeps the existing deliverables flow available.
    }
  }
  if (chatViewDisposed || sessionKey.value !== resourceSessionKey || workbenchOwnerKey.value !== visibleOwnerKey) return
  const allArtifactsUseWorkbench = sessionWorkbenchArtifacts.value.length
    === sessionArtifacts.value.length
  if (workbenchEnabled.value && allArtifactsUseWorkbench) {
    const recentPreview = workbenchStore.findMostRecentItem(item => {
      if (
        item.kind !== 'artifact-preview'
        || item.scope.type !== 'session'
        || item.scope.id !== workbenchOwnerKey.value
        || item.payload.sessionKey !== sessionKey.value
      ) return false
      const artifact = artifactFromWorkbenchItem(item)
      if (!artifact) return false
      return artifactUsesDocumentWorkbench(artifact)
    })
    if (recentPreview) {
      workbenchStore.activateItem(recentPreview.id)
      workbenchStore.setExpanded(true)
      workbenchStore.requestReveal()
      return
    }

    for (let index = sessionWorkbenchArtifacts.value.length - 1; index >= 0; index -= 1) {
      const artifact = sessionWorkbenchArtifacts.value[index]
      if (!artifact) continue
      openArtifact(artifact)
      return
    }
  }
  deliverablesOpen.value = true
}

function focusInlineDeliverable(artifact: ArtifactPayload): boolean {
  const reduceMotion = typeof window !== 'undefined'
    && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches
  const card = findArtifactCard(threadRef.value, artifact)
  if (!card) return false
  beginActiveThreadNavigation(!reduceMotion)
  return focusArtifactInTranscript(
    threadRef.value,
    artifact,
    reduceMotion ? 'auto' : 'smooth',
  )
}

let workbenchArtifactInventoryFingerprint = ''

watch(sessionArtifacts, artifacts => {
  if (!sessionKey.value) return
  const nextInventoryFingerprint = [
    sessionKey.value,
    ...artifacts.map(artifact => String(
      artifact.id || artifact.key || artifact.download_url || artifact.name || '',
    )),
  ].join('\u0000')
  if (
    nextInventoryFingerprint !== workbenchArtifactInventoryFingerprint
    && workbenchResourcesEnabled.value
    && workbenchEnabled.value
  ) {
    workbenchArtifactInventoryFingerprint = nextInventoryFingerprint
    void workbenchResourcesStore.load(sessionKey.value, true).catch(() => undefined)
  }
  artifactImageLightbox.updateNavigation(artifacts, sessionKey.value)
  if (!workbenchEnabled.value) return
  for (const item of workbenchStore.items) {
    if (
      item.kind !== 'artifact-preview'
      || item.scope.type !== 'session'
      || item.scope.id !== workbenchOwnerKey.value
      || item.payload.sessionKey !== sessionKey.value
    ) continue
    const artifact = artifactFromWorkbenchItem(item)
    if (!artifact) continue
    // Inventory refresh changes navigation only. Preserve the child's resource
    // authority, parent visibility, prepared preview and explicit section request.
    workbenchStore.updateItem({
      ...item,
      payload: { ...item.payload, navigationArtifacts: [...artifacts] },
    })
  }
})

function openLegacyArtifactWorkbench(
  artifact: ArtifactPayload,
  initialSection: 'preview' | 'source' = 'preview',
): boolean {
  return openWorkbenchItemExplicit(artifactPreviewItemForExplicitOpen({
    artifact,
    initialSection,
    navigationArtifacts: sessionArtifacts.value,
    nativeHtml: Boolean(
      platform.capabilities.hasNativeWorkbenchSurfaces
      && platform.workbench.native,
    ),
    sessionKey: sessionKey.value,
    ...(artifact.id ? { resourceIdentity: `deliverable:${artifact.id}` } : {}),
  }))
}

async function openDeliverableWorkbenchResource(artifact: ArtifactPayload) {
  const key = sessionKey.value
  const isCurrent = beginWorkbenchPreviewRequest()
  if (!isCurrent()) return
  const artifactId = typeof artifact.id === 'string' ? artifact.id.trim() : ''
  const documentId = typeof artifact.documentId === 'string'
    ? artifact.documentId.trim()
    : typeof artifact.document_id === 'string' ? artifact.document_id.trim() : ''
  try {
    const historical = artifact.workbenchOpenIntent === 'history'
    if (!historical && artifact.source === 'workspace-preview') {
      await openWorkspacePreviewExplicit(
        documentId || { artifactId }, key,
        typeof artifact.previewPagePath === 'string' ? artifact.previewPagePath : undefined,
      )
      return
    }
    if (!artifactId || !key) {
      openLegacyArtifactWorkbench(artifact)
      return
    }
    const ref = createWorkbenchResourceRef('deliverable', artifactId)
    const resource = historical
      ? await workbenchResourcesStore.resolve(key, ref)
      : await resolveCurrentDocumentResource(
          (session, resource) => workbenchResourcesStore.resolveFresh(session, resource, isCurrent), key, ref, isCurrent)
    if (!isCurrent()) return
    if (!resource) {
      openLegacyArtifactWorkbench(artifact)
      return
    }
    if (!resource.capabilities.preview) {
      pushToast(t(workbenchResourceUnavailableReasonKey(
        workbenchResourceActionReasonCode(resource.capabilities, 'preview'),
      )), { tone: 'warn' })
      return
    }
    // Discovery follows existing Document lineage without importing a copy.
    // Explicit history retains the immutable delivery and its own tab.
    const previewArtifact = historical ? artifactPayloadFromWorkbenchResource(resource)
      : await prepareCurrentDocumentPreview(resource, key, artifactDocumentsStore, isCurrent)
    if (!isCurrent() || !previewArtifact) return
    openWorkbenchItemExplicit(artifactPreviewItemForExplicitOpen({
      artifact: previewArtifact,
      historical,
      navigationArtifacts: sessionArtifacts.value,
      nativeHtml: Boolean(platform.capabilities.hasNativeWorkbenchSurfaces && platform.workbench.native),
      resourceIdentity: workbenchResourceKey(resource.resource),
      sessionKey: key,
    }))
  } catch (error) {
    if (!isCurrent()) return
    const classified = classifyArtifactProductError(error)
    const translated = t(classified.messageKey)
    pushToast(translated === classified.messageKey ? classified.fallbackMessage : translated,
      { tone: 'danger', duration: 9000 })
  }
}

async function resolveWorkspacePreviewResource(key: string, documentId: string) {
  if (!attachmentWorkbenchPreviewEnabled.value) return null
  const ref = createWorkbenchResourceRef('document', documentId)
  return workbenchResourcesStore.resolve(key, ref)
}

const workspacePreviewOpening = useWorkspacePreviewOpening({
  sessionKey,
  currentEpoch,
  beginRequest: beginWorkbenchPreviewRequest,
  enabled: attachmentWorkbenchPreviewEnabled,
  getArtifact: (key, artifactId) => artifactWorkbench.artifacts.get(key, artifactId),
  resolve: (key, resource) => workbenchResourcesStore.resolve(key, resource),
  openCurrent: (key, resource) => workbenchResourcesStore.openCurrent(key, resource),
  prepareCurrent: (current, key, isCurrent) => prepareCurrentDocumentPreview(current.resource, key, artifactDocumentsStore, isCurrent),
  show: (current, key, previewPagePath) => {
    const artifact = artifactPayloadFromRevision(current.revision)
    artifact.documentId = current.document.documentId
    artifact.revisionId = current.revision.revisionId
    artifact.sourcePath = current.resource.sourcePath
    if (previewPagePath) artifact.previewPagePath = previewPagePath
    const item = artifactPreviewItemForExplicitOpen({
      artifact,
      initialSection: 'preview',
      navigationArtifacts: sessionArtifacts.value,
      nativeHtml: Boolean(platform.capabilities.hasNativeWorkbenchSurfaces && platform.workbench.native),
      previewLeaseEligible: true,
      resourceIdentity: workbenchResourceKey(current.resource.resource),
      sessionKey: key,
    })
    // A live result still registers its resource while its conversation is
    // hidden, but must not take over another conversation or the new-chat page.
    return workbenchStore.openItem(item, {
      activate: item.scope.type !== 'session' || item.scope.id === workbenchStore.activeSessionId,
    })
  },
  onError: error => {
    const classified = classifyArtifactProductError(error)
    const translated = t(classified.messageKey)
    pushToast(translated === classified.messageKey ? classified.fallbackMessage : translated,
      { tone: 'danger', duration: 9000 })
  },
})

async function openWorkspacePreviewExplicit(...args: Parameters<typeof workspacePreviewOpening.open>) {
  const owner = workbenchOwnerKey.value
  const opened = await workspacePreviewOpening.open(...args)
  if (opened && owner === workbenchOwnerKey.value && owner === workbenchStore.activeSessionId) {
    workbenchStore.requestReveal()
  }
}

function openArtifact(artifact: ArtifactPayload): boolean {
  // All file entry points share ordering, including synchronous legacy/media
  // opens that must retire an older document request still awaiting transport.
  const isCurrent = beginWorkbenchPreviewRequest()
  if (!isCurrent()) return false
  // Persisted artifacts also carry this provenance. Only id-less workspace
  // actions already carry the document/session identity needed by this helper.
  if (artifact.source === 'workspace-preview' && !artifact.id) {
    void openWorkspacePreviewExplicit(
      typeof artifact.documentId === 'string' ? artifact.documentId : '',
      artifact.session_key || '',
      typeof artifact.previewPagePath === 'string' ? artifact.previewPagePath : undefined,
    )
    return true
  }
  // Generated images are also inline media. Route every visual artifact to
  // the authenticated lightbox before the inline-focus fallback so clicking
  // either the thumbnail or its open affordance actually previews it.
  if (artifactCategory(artifact) === 'visual' && sessionKey.value) {
    artifactImageLightbox.open({
      artifact,
      navigationArtifacts: sessionArtifacts.value,
      sessionKey: sessionKey.value,
      ownerSessionKey: workbenchOwnerKey.value,
    })
    return true
  }
  if (
    isInlineMediaArtifact(artifact)
    || (
      artifactWorkbenchPreviewKind(artifact) === 'unsupported'
      && !isOfficeArtifact(artifact)
    )
  ) {
    return focusInlineDeliverable(artifact)
  }
  if (!workbenchEnabled.value || !sessionKey.value) return false
  if (
    attachmentWorkbenchPreviewEnabled.value
    && (
      artifactWorkbenchPreviewKind(artifact) === 'html'
      || isOfficePreviewFormat(artifactWorkbenchPreviewKind(artifact))
    )
    && (
      (typeof artifact.id === 'string' && artifact.id.trim())
      || (typeof artifact.documentId === 'string' && artifact.documentId.trim())
      || (typeof artifact.document_id === 'string' && artifact.document_id.trim())
    )
  ) {
    void openDeliverableWorkbenchResource(artifact)
    return true
  }
  return openLegacyArtifactWorkbench(artifact)
}

function closeDeliverables() {
  deliverablesOpen.value = false
  focusHeaderAction('deliverables')
}

/* ── Fork ──────────────────────────────────────────────────────────── */

function clearForkTransition(generation?: number) {
  if (
    generation !== undefined
    && forkTransition.value?.generation !== generation
  ) return
  const clearedGeneration = generation ?? forkTransition.value?.generation
  forkTransition.value = null
  forkTransitionLifetime.invalidate(clearedGeneration)
}

function isForkTransitionActive(generation: number): boolean {
  return Boolean(
    chatViewActive
    && !chatViewDisposed
    && forkTransitionLifetime.isCurrent(generation)
    && forkTransition.value?.generation === generation
  )
}

function failForkTransition(
  generation: number,
  reason: NonNullable<ForkTransitionState['errorReason']>,
  error: unknown,
) {
  if (!isForkTransitionActive(generation)) return
  const transition = forkTransition.value!
  console.warn('Fork child hand-off failed:', error instanceof Error ? error.message : error)
  const firstFailure = transition.phase !== 'error'
  forkTransition.value = {
    ...transition,
    phase: 'error',
    errorReason: reason,
  }
  if (firstFailure) pushToast(t('chat.toast.forkOpenFailed'), { tone: 'warn' })
}

async function retryForkTransition() {
  const transition = forkTransition.value
  if (
    !transition?.targetKey
    || transition.phase !== 'error'
    || !isForkTransitionActive(transition.generation)
  ) return
  const retryPhase = forkNavigationPhase(transition.targetKey, transition.parentKey)
  forkTransition.value = {
    ...transition,
    phase: retryPhase,
    errorReason: undefined,
  }
  try {
    if (
      sessionKey.value !== transition.targetKey
      || readSessionFromUrl() !== transition.targetKey
    ) {
      const navigationFailure = await router.push({
        path: '/chat',
        query: { session: transition.targetKey },
      })
      if (!isForkTransitionActive(transition.generation)) return
      if (navigationFailure && readSessionFromUrl() !== transition.targetKey) {
        throw navigationFailure
      }
      return
    }
    if (livePhase.value === 'degraded') void retryLive()
    void retryHistory()
  } catch (error) {
    failForkTransition(transition.generation, 'navigation', error)
  }
}

async function returnToForkParent() {
  const transition = forkTransition.value
  if (!transition || !isForkTransitionActive(transition.generation)) return
  if (
    sessionKey.value === transition.parentKey
    && readSessionFromUrl() === transition.parentKey
  ) {
    if (
      transition.targetKey === transition.parentKey
      && historySessionKey.value === transition.parentKey
      && historyState.value.initialLoadStatus !== 'ready'
    ) {
      if (transition.phase === 'error') {
        await retryForkTransition()
        if (!isForkTransitionActive(transition.generation)) return
      }
      return
    }
    clearForkTransition(transition.generation)
    return
  }
  forkTransition.value = {
    ...transition,
    targetKey: transition.parentKey,
    phase: 'returning',
    errorReason: undefined,
  }
  try {
    const navigationFailure = await router.push({
      path: '/chat',
      query: { session: transition.parentKey },
    })
    if (!isForkTransitionActive(transition.generation)) return
    if (navigationFailure && readSessionFromUrl() !== transition.parentKey) {
      throw navigationFailure
    }
  } catch (error) {
    failForkTransition(transition.generation, 'navigation', error)
  }
}

async function forkConversation(throughTurnId?: string) {
  const parentKey = sessionKey.value
  if (!parentKey || forkTransition.value) return
  if (pendingSessionIntent.value === 'new_chat' || isStreaming.value) return
  const normalizedTurnId = throughTurnId?.trim() || undefined
  const generation = forkTransitionLifetime.begin()
  if (!generation) return
  forkTransition.value = {
    generation,
    parentKey,
    childKey: '',
    targetKey: parentKey,
    ...(normalizedTurnId ? { throughTurnId: normalizedTurnId } : {}),
    phase: 'creating',
    previewMessages: snapshotForkPreviewMessages(renderedMessages.value, normalizedTurnId),
  }
  try {
    const res = await sessionLifecycle.fork({
      key: parentKey,
      ...(normalizedTurnId ? { throughTurnId: normalizedTurnId } : {}),
    })
    if (!isForkTransitionActive(generation)) return
    const childKey = res.key
    if (sessionKey.value !== parentKey) {
      clearForkTransition(generation)
      return
    }
    // The fork result carries only the child key; the sidebar row synthesized
    // before the next sessions.list snapshot would otherwise have no project
    // binding and float to the section's top level. Mirror adoptResponseSession:
    // carry the parent's project onto the child until the durable row confirms it.
    const forkWorkspaceId = freshTaskDraft.materializedWorkspaceBySession.value[parentKey]
      || boundWorkspaceId.value
    if (forkWorkspaceId) {
      freshTaskDraft.bindMaterializedProjectTask(childKey, forkWorkspaceId)
    }
    forkTransition.value = {
      ...forkTransition.value,
      childKey,
      targetKey: childKey,
      phase: 'opening',
    }
    const navigationFailure = await router.push({
      path: '/chat',
      query: { session: childKey },
    })
    if (!isForkTransitionActive(generation)) return
    if (navigationFailure && readSessionFromUrl() !== childKey) {
      throw navigationFailure
    }
  } catch (err) {
    if (!isForkTransitionActive(generation)) return
    const childCreated = Boolean(forkTransition.value?.childKey)
    if (childCreated) {
      failForkTransition(generation, 'navigation', err)
    } else if (forkTransition.value?.generation === generation) {
      console.warn('Fork failed:', err)
      clearForkTransition(generation)
      pushToast(t('chat.toast.forkFailed'), { tone: 'danger' })
    }
  }
}

// Owner recovery for a run paused by the sandbox denial ledger (the terminal
// error card exposes a Resume button). Clearing the pause lets the next turn
// proceed; the run itself already ended, so we prompt the user to resend.
const sandboxResumePending = ref(false)
const resumedSandboxTurn = ref<SandboxResumeIdentity | null>(null)
const eligibleSandboxResumeTurnId = computed(() => currentSandboxResumeTurnId(
  renderedMessages.value,
  {
    sessionKey: sessionKey.value,
    taskId: chatTaskId(runStatus.value.task),
    taskStatus: runStatus.value.status,
    connectionAvailable: gatewayAccess.isAvailable && gatewayAccess.isAuthenticated
      && livePhase.value === 'ready',
    busy: sessionHasActiveWork.value || chatSend.sendPending.value || isStopPending.value,
    shareMode: shareMode.value,
    forkPreview: Boolean(forkTransition.value),
  },
))

function sandboxResumeIdentity(): SandboxResumeIdentity {
  return {
    sessionKey: sessionKey.value,
    turnId: eligibleSandboxResumeTurnId.value,
    epoch: currentEpoch.value,
    viewEpoch: scrollEpoch.value,
  }
}

const sandboxResumeTurnId = computed(() => {
  if (sandboxResumePending.value) return ''
  if (resumedSandboxTurn.value && isCurrentSandboxResume(resumedSandboxTurn.value, sandboxResumeIdentity())) return ''
  return eligibleSandboxResumeTurnId.value
})

async function resumeSandbox(message: ChatRenderedMessage, sourceSessionKey: string) {
  const captured = sandboxResumeIdentity()
  if (chatViewDisposed || !sandboxResumeTurnId.value
    || sourceSessionKey !== captured.sessionKey
    || sandboxResumeMessageTurnId(message) !== captured.turnId) return
  sandboxResumePending.value = true
  const isCurrent = () => !chatViewDisposed && isCurrentSandboxResume(captured, sandboxResumeIdentity())
  try {
    const result = await sandboxRuntime.resumeSession(captured.sessionKey)
    if (!isCurrent()) return
    if (result.sessionKey !== captured.sessionKey || result.autonomousPaused) {
      pushToast(localizedChatErrorMessage(undefined, ''), { tone: 'danger' })
      return
    }
    resumedSandboxTurn.value = captured
    messages.value.push({
      role: 'system',
      text: t('chat.sandboxResumed'),
      ts: new Date().toISOString(),
    })
  } catch (err) {
    console.warn('Sandbox resume failed:', err)
    if (isCurrent()) pushToast(localizedChatErrorMessage(undefined, ''), { tone: 'danger' })
  } finally {
    sandboxResumePending.value = false
  }
}

const {
