import type { ArtifactPayload } from '@/types/artifacts'
import type { WorkbenchPreviewDescriptor, WorkbenchResourceRef, WorkbenchResourceType } from '@/types/workbenchResources'
import { createWorkbenchResourceRef, workbenchResourceRefId } from '@/types/workbenchResources'
import {
  artifactFileTitle,
  isOfficeArtifact,
} from '@/utils/chat/artifacts'
import {
  artifactUsesWorkbenchPreview,
  artifactWorkbenchPreviewKind,
} from '@/utils/workbench/artifactPreview'
import type { WorkbenchItem } from './types'
import { previewPagePathFromUrl } from '@/utils/workbench/previewPagePath'

const BASE64_URL_ALPHABET =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'

function fnv64(bytes: Uint8Array, seed: bigint): string {
  let hash = seed
  for (const byte of bytes) {
    hash ^= BigInt(byte)
    hash = BigInt.asUintN(64, hash * 0x100000001b3n)
  }
  return hash.toString(16).padStart(16, '0')
}

function privateIdentityDigest(value: string): string {
  const bytes = new TextEncoder().encode(value)
  return [
    fnv64(bytes, 0xcbf29ce484222325n),
    fnv64(bytes, 0x84222325cbf29ce4n),
  ].join('')
}

function base64Url(bytes: Uint8Array): string {
  let result = ''
  for (let index = 0; index < bytes.length; index += 3) {
    const first = bytes[index] ?? 0
    const second = bytes[index + 1] ?? 0
    const third = bytes[index + 2] ?? 0
    const packed = (first << 16) | (second << 8) | third
    result += BASE64_URL_ALPHABET[(packed >>> 18) & 63]
    result += BASE64_URL_ALPHABET[(packed >>> 12) & 63]
    if (index + 1 < bytes.length) result += BASE64_URL_ALPHABET[(packed >>> 6) & 63]
    if (index + 2 < bytes.length) result += BASE64_URL_ALPHABET[packed & 63]
  }
  return result
}

/**
 * Artifact identities are normally server-issued IDs and can be represented
 * losslessly. Long legacy fallbacks use a 128-bit digest plus byte length so a
 * tab key stays inside the native surface ID limit without the 32-bit collision
 * class that could alias two old-history artifacts.
 */
function artifactIdentityToken(value: string): string {
  const bytes = new TextEncoder().encode(value)
  const encoded = base64Url(bytes)
  return encoded.length <= 56
    ? `v${bytes.length.toString(36)}-${encoded}`
    : `h${bytes.length.toString(36)}-${privateIdentityDigest(value)}`
}

function artifactIdentity(artifact: ArtifactPayload): string {
  return String(
    artifact.id
      || artifact.key
      || artifact.download_url
      || `${artifact.name || 'artifact'}:${artifact.mime || ''}:${artifact.size || ''}`,
  )
}

export function artifactWorkbenchItemId(
  sessionKey: string,
  artifact: ArtifactPayload,
  resourceIdentity?: string,
): string {
  return [
    'artifact-preview',
    privateIdentityDigest(sessionKey),
    artifactIdentityToken(resourceIdentity || artifactIdentity(artifact)),
  ].join(':')
}

export function createArtifactPreviewWorkbenchItem(options: {
  artifact: ArtifactPayload
  historical?: boolean
  initialSection?: 'preview' | 'source'
  initialSectionRequestId?: number
  navigationArtifacts?: readonly ArtifactPayload[]
  nativeHtml: boolean
  preparedPreview?: WorkbenchPreviewDescriptor
  previewLeaseEligible?: boolean
  resourceIdentity?: string
  sessionKey: string
}): WorkbenchItem {
  const {
    artifact,
    historical = artifact.workbenchOpenIntent === 'history',
    initialSection = 'preview',
    initialSectionRequestId = 0,
    navigationArtifacts = [],
    nativeHtml,
    preparedPreview,
    previewLeaseEligible = true,
    resourceIdentity,
    sessionKey,
  } = options
  const kind = artifactWorkbenchPreviewKind(artifact)
  return {
    id: artifactWorkbenchItemId(sessionKey, artifact, resourceIdentity),
    kind: 'artifact-preview',
    title: artifactFileTitle(artifact),
    scope: { type: 'session', id: sessionKey },
    hostKind: nativeHtml && kind === 'html' ? 'native-webcontents' : 'dom',
    // DOM previews own cancellable fetches and Blob URLs. Recreate them on
    // activation instead of retaining every opened document indefinitely.
    // Native HTML surfaces have their own isolated lifecycle and stay mounted.
    retention: nativeHtml && kind === 'html' ? 'keep-alive' : 'dispose-on-suspend',
    payload: {
      artifact: historical ? { ...artifact, workbenchOpenIntent: 'history' } : artifact,
      ...(historical ? { historical: true } : {}),
      ...(typeof artifact.sourcePath === 'string' && artifact.sourcePath.trim()
        ? { sourcePath: artifact.sourcePath.trim() } : {}),
      initialSection,
      initialSectionRequestId,
      navigationArtifacts: [...navigationArtifacts],
      ...(preparedPreview
        ? {
            preparedPreview: {
              ...preparedPreview,
              resource: { ...preparedPreview.resource },
              ...(preparedPreview.adapter
                ? { adapter: { ...preparedPreview.adapter } }
                : {}),
            },
          }
        : {}),
      previewLeaseEligible,
      resourceIdentity: resourceIdentity || artifactIdentity(artifact),
      sessionKey,
    },
  }
}

export function initialSectionFromWorkbenchItem(
  item: WorkbenchItem | null,
): 'preview' | 'source' {
  return item?.kind === 'artifact-preview' && item.payload.initialSection === 'source'
    ? 'source'
    : 'preview'
}

export function initialSectionRequestIdFromWorkbenchItem(
  item: WorkbenchItem | null,
): number {
  const value = item?.kind === 'artifact-preview'
    ? item.payload.initialSectionRequestId
    : 0
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0
    ? value
    : 0
}

/**
 * Mark an explicit user request to open a preview section. Metadata-only item
 * refreshes must preserve the existing request id instead of calling this.
 */
export function requestInitialSectionForWorkbenchItem(
  item: WorkbenchItem,
  existing: WorkbenchItem | null,
): WorkbenchItem {
  const previousRequestId = existing?.id === item.id
    ? initialSectionRequestIdFromWorkbenchItem(existing)
    : 0
  const initialSectionRequestId = previousRequestId < Number.MAX_SAFE_INTEGER
    ? previousRequestId + 1
    : 1
  return {
    ...item,
    payload: {
      ...item.payload,
      initialSectionRequestId,
    },
  }
}

/**
 * Returns only the fail-closed preview policy accepted by the Workbench RPC.
 * Arbitrary item payloads cannot opt a normal document preview into this path.
 */
export function preparedPreviewFromWorkbenchItem(
  item: WorkbenchItem | null,
): WorkbenchPreviewDescriptor | null {
  if (item?.kind !== 'artifact-preview') return null
  const value = item.payload.preparedPreview
  if (!value || typeof value !== 'object') return null
  const preview = value as Record<string, unknown>
  const resource = preview.resource
  if (!resource || typeof resource !== 'object') return null
  const ref = resource as Record<string, unknown>
  if (
    !((preview.mode === 'isolated' && preview.sandboxProfile === 'opaque-offline')
      || (preview.mode === 'local-renderer' && preview.sandboxProfile === 'none'
        && preview.adapter && typeof preview.adapter === 'object'
        && (preview.adapter as Record<string, unknown>).id === 'silurus-office'
        && (preview.adapter as Record<string, unknown>).version === '0.88.0'
        && ['docx', 'pptx', 'xlsx'].includes(String((preview.adapter as Record<string, unknown>).format))))
    || preview.network !== false
    || typeof preview.protocolVersion !== 'number'
    || typeof ref.type !== 'string'
    || typeof ref.id !== 'string'
  ) return null
  return value as WorkbenchPreviewDescriptor
}

export function artifactFromWorkbenchItem(
  item: WorkbenchItem | null,
): ArtifactPayload | null {
  if (item?.kind !== 'artifact-preview') return null
  const artifact = item.payload.artifact
  return artifact && typeof artifact === 'object'
    ? artifact as ArtifactPayload
    : null
}

/** Only typed resource identities carry Document authority. Legacy artifact IDs do not. */
export function artifactResourceRefFromWorkbenchItem(item: WorkbenchItem): WorkbenchResourceRef | null {
  if (item.kind !== 'artifact-preview') return null
  const accepted = new Set<WorkbenchResourceType>(['attachment', 'document', 'deliverable', 'url'])
  const prepared = preparedPreviewFromWorkbenchItem(item)
  if (prepared && accepted.has(prepared.resource.type)) {
    const id = workbenchResourceRefId(prepared.resource).trim()
    if (id) return createWorkbenchResourceRef(prepared.resource.type, id)
  }
  const identity = typeof item.payload.resourceIdentity === 'string' ? item.payload.resourceIdentity : ''
  const match = /^(attachment|document|deliverable|url):(.+)$/.exec(identity)
  if (match?.[2]?.trim()) return createWorkbenchResourceRef(match[1] as WorkbenchResourceType, match[2].trim())
  const artifact = artifactFromWorkbenchItem(item)
  const type = artifact?.workbenchResourceType
  const id = artifact?.workbenchResourceId
  return typeof type === 'string' && accepted.has(type as WorkbenchResourceType)
    && typeof id === 'string' && id.trim()
    ? createWorkbenchResourceRef(type as WorkbenchResourceType, id.trim()) : null
}

/** Unscoped legacy previews stay read-only; this does not authorize a Deliverable operation. */
export function isFixedArtifactPreview(item: WorkbenchItem): boolean {
  return item.kind === 'artifact-preview' && (
    artifactIsHistoricalPreview(item) || artifactResourceRefFromWorkbenchItem(item)?.type !== 'document'
  )
}

/** Display state is explicit: an immutable preview must never silently follow head. */
export function artifactIsHistoricalPreview(item: WorkbenchItem): boolean {
  return item.kind === 'artifact-preview' && (
    item.payload.historical === true
    || artifactFromWorkbenchItem(item)?.workbenchOpenIntent === 'history'
  )
}

/** Only authorized relative paths supplied by the resource projection are shown. */
export function artifactSourcePathFromWorkbenchItem(item: WorkbenchItem): string {
  if (item.kind !== 'artifact-preview') return ''
  const path = item.payload.sourcePath ?? artifactFromWorkbenchItem(item)?.sourcePath
  return typeof path === 'string' ? path.trim() : ''
}

/** Use the immutable revision URL or the original ArtifactStore ID. */
export function fixedArtifactTarget(artifact: ArtifactPayload): ArtifactPayload {
  if (!artifact.id) return artifact
  return { ...artifact, source: 'artifact', download_url: artifact.revision_download_url || undefined }
}

/** File operations follow the displayed Document, never a related delivery. */
export function fileActionArtifactFromWorkbenchItem(
  item: WorkbenchItem, state: Readonly<Record<string, unknown>>,
): ArtifactPayload | undefined {
  const artifact = artifactFromWorkbenchItem(item)
  if (!artifact) return
  if (isFixedArtifactPreview(item)) return fixedArtifactTarget(artifact)
  const prepared = preparedPreviewFromWorkbenchItem(item)
  if (prepared && prepared.resource.type !== 'document') return artifact
  const documentId = typeof state.workingFileDocumentId === 'string' && state.workingFileDocumentId
    ? state.workingFileDocumentId
    : typeof artifact.documentId === 'string'
      && item.payload.resourceIdentity === `document:${artifact.documentId}` ? artifact.documentId : ''
  if (!documentId) return artifact
  if (state.workingFilePageUnknown === true) return
  const pagePath = state.previewLaunchUrl ? previewPagePathFromUrl(
    String(state.currentUrl || state.previewLaunchUrl), {
      launch_url: String(state.previewLaunchUrl), entrypoint: String(state.workingFileEntrypoint || ''),
      page_path: String(state.workingFileInitialPage || ''),
    },
  ) : artifact.previewPagePath
  if (state.previewLaunchUrl && !pagePath) return
  return { ...artifact, source: 'workspace-preview', documentId,
    ...(pagePath ? { previewPagePath: pagePath } : {}) }
}

export function navigationArtifactsFromWorkbenchItem(
  item: WorkbenchItem | null,
): readonly ArtifactPayload[] {
  if (item?.kind !== 'artifact-preview') return []
  const artifacts = item.payload.navigationArtifacts
  return Array.isArray(artifacts)
    ? artifacts.filter(
      (artifact): artifact is ArtifactPayload =>
        Boolean(artifact) && typeof artifact === 'object',
    )
    : []
}

export function previewableNavigationArtifactsFromWorkbenchItem(
  item: WorkbenchItem | null,
): readonly ArtifactPayload[] {
  return navigationArtifactsFromWorkbenchItem(item)
    .filter(artifact => artifactUsesWorkbenchPreview(artifact) || isOfficeArtifact(artifact))
}

export function sessionKeyFromWorkbenchItem(item: WorkbenchItem | null): string {
  if (!item || item.scope.type !== 'session') return ''
  // A side-chat preview or collection is visible in the parent scope, while its
  // document bytes remain authorized against the ephemeral child session.
  // Keep those identities separate: scope controls visibility/lifetime and
  // payload.sessionKey controls artifact/resource reads.
  if ((item.kind === 'artifact-preview' || item.kind === 'file' || item.kind === 'resource-collection') && typeof item.payload.sessionKey === 'string'
    && item.payload.sessionKey.trim()) return item.payload.sessionKey
  return item.scope.id
}
