const MAX_PENDING = 5
const MAX_REMOVAL_TOMBSTONES = 256
const MAX_PROMPT_ANNOTATION_IDS = 16

function normalizeAnnotationDraftIds(
  ids: unknown,
): string[] {
  return (Array.isArray(ids) ? ids : [])
    .map(value => String(value || '').trim())
    .filter((value, index, values) => Boolean(value) && values.indexOf(value) === index)
    .slice(0, MAX_PROMPT_ANNOTATION_IDS)
}

type PendingReorderMode = 'local' | 'server'

interface PendingReorderSnapshot {
  sessionKey: string
  deliveryIdentity: string | null
  mode: PendingReorderMode
  originalOrder: string[]
  expectedWalRevisions: Record<string, number>
  started?: boolean
  commit?: Promise<void>
  deferredHydrate?: boolean
}

interface ComposerAttachmentSnapshotEntry {
  readonly identity: Attachment
  readonly content: Readonly<Record<string, unknown>>
  readonly workspaceFile: string | undefined
}

type ComposerAttachmentSnapshot = ReadonlyArray<ComposerAttachmentSnapshotEntry>

function snapshotComposerAttachments(
  attachments: readonly Attachment[],
): ComposerAttachmentSnapshot {
  return Object.freeze(attachments.map(attachment => Object.freeze({
    identity: attachment,
    content: Object.freeze({ ...attachment }) as Readonly<Record<string, unknown>>,
    workspaceFile: JSON.stringify(attachment.workspaceFile),
  })))
}

function composerAttachmentsMatch(
  attachments: readonly Attachment[],
  snapshot: ComposerAttachmentSnapshot,
): boolean {
  if (attachments.length !== snapshot.length) return false
  return attachments.every((attachment, index) => {
    const expected = snapshot[index]
    if (!expected || attachment !== expected.identity) return false
    const current = attachment as unknown as Record<string, unknown>
    const currentKeys = Object.keys(current)
    const expectedKeys = Object.keys(expected.content)
    return currentKeys.length === expectedKeys.length
      && JSON.stringify(attachment.workspaceFile) === expected.workspaceFile
      && expectedKeys.every(key => (
        Object.prototype.hasOwnProperty.call(current, key)
        && Object.is(current[key], expected.content[key])
      ))
  })
}

interface PendingQueueBroadcastMessage {
  sessionKey?: unknown
  pendingInputId?: unknown
  action?: unknown
}

export type BusySendMode = 'queue' | 'steer'
export type PendingDeliveryOutcome =
  | 'accepted'
  | 'deferred'
  | 'not_sent'
  | 'retryable_failure'

export interface PendingQueueOwner {
  ownerRequestId?: string
}

export interface PendingCancelOptions {
  retainAfterCancel?: boolean
}

export interface PendingQueueOwnerContext {
  sessionKey: string
  ownerRequestId: string
}

export interface PendingQueuePayload {
  text: string
  turnCommand?: ProjectInitTurnCommand
  localPathReferences?: string[]
  draftIds?: readonly string[]
  selectedSkills?: SelectedSkillRef[]
  pageContext?: ChatPageContext
  attachments?: Attachment[]
  intent?: string | null
  confirmedPlainText?: boolean
  deliveryIdentity?: string
}

export interface PendingSteerPayload {
  request: SessionSteerV2Params
  phase?: PendingSteerPhase
}

export interface UseChatPendingQueueOptions {
  supportsTurnCommand?: (command: ProjectInitTurnCommand) => Promise<boolean>
  sessionKey: Ref<string>
  ownerContext?: Readonly<Ref<PendingQueueOwnerContext | null>>
  inputText: Ref<string>
  localPathReferences?: Ref<string[]>
  restoreInput?: (text: string, paths?: readonly string[]) => void
  pendingAttachments: Ref<Attachment[]>
  selectedSkills?: Ref<SelectedSkillRef[]>
  pendingSessionIntent: Ref<string | null>
  isStreaming: Ref<boolean>
  isBlocked: () => boolean
  autoResizeTextarea: () => void
  sendCurrentInput: () => void
  resetInputHistory: () => void
  hasComposer: () => boolean
  pendingInputWal?: PendingInputWal | null
  pendingQueuePolicy?: ReturnType<typeof createPendingQueuePolicy>
  pendingInputQueue?: PendingInputQueuePort | null
  connectionState?: Readonly<Ref<string>>
  deliveryIdentity?: Readonly<Ref<string | null>>
  composerRevision?: Readonly<Ref<number>>
  prepareAttachmentsForSend?: (options: {
    attachments: Attachment[]
    isCurrent?: () => boolean
  }) => Promise<boolean>
  onPendingPersistenceError?: (
    reason: 'wal_failed' | 'attachments_unsupported' | 'server_rejected' | 'order_conflict' | 'pause_failed',
  ) => void
  // The WebUI drains visible queue items through the same composer-preserving
  // transport used by explicit Steer. The legacy callback remains as a
  // fallback for isolated composable consumers.
  dispatchPendingItem?: (
    item: ChatPendingItem,
    ownerSessionKey: string,
    preDispatchGuard?: () => boolean,
  ) => Promise<PendingDeliveryOutcome>
}

export function useChatPendingQueue(options: UseChatPendingQueueOptions) {
  const pendingInputQueue = options.pendingInputQueue
  const pendingQueue = ref<ChatPendingItem[]>([])
  const queuePolicy = options.pendingQueuePolicy ?? createPendingQueuePolicy()
  const queuePolicyRevision = ref(0)
  const queueScope = () => ({
    sessionKey: options.sessionKey.value,
    deliveryIdentity: options.deliveryIdentity?.value || '',
  })
  const autoSendPaused = computed(() => {
    void queuePolicyRevision.value
    return queuePolicy.read(queueScope()).paused
  })
  // A reorder belongs to its queue, not to whichever composer is visible when
  // IndexedDB/RPC completes. Keep only the small transaction here; navigating
  // away never has to await it or keep the old transcript reader alive.
  const pendingReorders = shallowReactive(new Map<string, PendingReorderSnapshot>())
  const reorderOwnerKey = (sessionKey: string, identity = options.deliveryIdentity?.value ?? null) => (
    JSON.stringify([sessionKey, identity])
  )
  const activeReorder = () => pendingReorders.get(reorderOwnerKey(options.sessionKey.value))
  const isReordering = computed(() => Boolean(activeReorder()))
  const parkedQueues: ParkedPendingQueueCache = new ParkedPendingQueueCache({
    unwrapObject: toRaw,
    isPinned: item => Boolean(item.steerAttempt || item.deliveryState
      || item.ownerRequestId || item.pendingPersistenceState === 'cancelling' || (item.pendingInputId && (
        locallyCreatingIds.has(item.pendingInputId) || stagingOperations.has(item.pendingInputId)
        || cancellationOperations.has(item.pendingInputId)
      )) || [...pendingReorders.values()].some(reorder => reorder.sessionKey === item.ownerSessionKey)
      || pendingQueue.value.some(active => toRaw(active) === toRaw(item))),
    isUrlRetained: url => [options.pendingAttachments.value,
      ...pendingQueue.value.map(item => item.attachments),
      ...[...parkedQueues.values()].flat().map(item => item.attachments),
    ].some(attachments => attachments.some(attachment => attachment.dataUrl === url)),
  })
  let pendingDrainTimer: ReturnType<typeof setTimeout> | null = null
  let deferredDrainRequested = false
  let hydrateGeneration = 0
  let disposed = false
  const stagingOperations = new Map<string, Promise<void>>()
  const cancellationOperations = new Map<string, Promise<boolean>>()
  const locallyCreatingIds = new Set<string>()
  const removedIdentityOrder: string[] = []
  const removedIdentities = new Set<string>()
  const broadcast = options.pendingInputWal && typeof BroadcastChannel !== 'undefined'
    ? new BroadcastChannel('opensquilla.pending-chat-inputs.v1')
    : null

  // A not-yet-durable Steer owns a separate transport slot. It must not
  // consume one of the five ordinary follow-up slots, regardless of whether
  // the Steer or the drafts were queued first.
  const ordinaryPendingCount = computed(() =>
    pendingQueue.value.filter(item => !item.steerAttempt).length,
  )
  const canQueueMore = computed(() => ordinaryPendingCount.value < MAX_PENDING)
  const canReorder = computed(() => pendingReorderMode() !== null)
  // A direct queued delivery owns its item until it succeeds, is removed, or
  // becomes eligible for another explicit retry.
  const hasDeliveryBarrier = computed(() =>
    pendingQueue.value.some(
      item => Boolean(
        item.deliveryState
        || item.steerAttempt
        || item.pendingPersistenceState === 'saving'
        || item.pendingPersistenceState === 'cancelling',
      ),
    ),
  )
  const canSendFollowup = computed(() => !options.isStreaming.value
    && !options.isBlocked() && !isReordering.value)

  function refreshQueuePolicy() {
    queuePolicyRevision.value += 1
    if (autoSendPaused.value) clearPendingDrainAfterTerminalTimer()
  }
  const policyStorageListener = (event: StorageEvent) => {
    if (event.key === null || queuePolicy.isScopeStorageKey(queueScope(), event.key)) refreshQueuePolicy()
  }
  if (typeof window !== 'undefined') window.addEventListener('storage', policyStorageListener)

  function pausePendingAutoSend() {
    const result = queuePolicy.pause(queueScope())
    refreshQueuePolicy()
    broadcastChange(options.sessionKey.value)
    if (!result.persisted) options.onPendingPersistenceError?.('pause_failed')
  }

  function resumePendingAutoSend() {
    const result = queuePolicy.resume(queueScope())
    refreshQueuePolicy()
    broadcastChange(options.sessionKey.value)
    if (!result.persisted) options.onPendingPersistenceError?.('pause_failed')
    if (!result.paused) schedulePendingDrainAfterTerminal()
  }

  function capturePendingAutoSendResume(): () => void {
    const scope = queueScope()
    const captured = queuePolicy.read(scope)
    return () => {
      if (disposed || !captured.paused || !captured.persisted
        || scope.sessionKey !== options.sessionKey.value
        || scope.deliveryIdentity !== (options.deliveryIdentity?.value || '')) return
      const result = queuePolicy.resumeGeneration(scope, captured.generation)
      if (!result) return
      refreshQueuePolicy()
      broadcastChange(scope.sessionKey)
      if (!result.persisted) options.onPendingPersistenceError?.('pause_failed')
      if (!result.paused) schedulePendingDrainAfterTerminal()
    }
  }

  // A permit belongs to one dispatch. An explicit click may send one held item,
  // but cannot change the policy for the rest or survive a later Stop.
  function captureFollowupGuard(ownerSessionKey: string, explicit = false): () => boolean {
    const scope = queueScope()
    const permit = queuePolicy.capture(scope, explicit)
    return () => !disposed && ownerSessionKey === options.sessionKey.value
      && scope.sessionKey === ownerSessionKey
      && scope.deliveryIdentity === (options.deliveryIdentity?.value || '')
      && queuePolicy.allows(permit)
  }

  // Busy-composer delivery mode: 'queue' holds the message until the turn
  // ends (pending queue), 'steer' sends it immediately into the active run.
  // The choice only applies while a run is active, so it snaps back to the
  // safe default whenever streaming stops.
  const busySendMode = ref<BusySendMode>('queue')
  watch(options.isStreaming, (streaming) => {
    if (!streaming) {
      busySendMode.value = 'queue'
      flushDeferredPendingDrain()
    }
  })
  watch(hasDeliveryBarrier, (blocked, wasBlocked) => {
    if (blocked) {
      cancelPendingDrainTimer()
    } else if (wasBlocked) {
      flushDeferredPendingDrain()
    }
  })
  if (options.connectionState) {
    watch(options.connectionState, state => {
      if (state !== 'connected') return
      void hydratePendingQueue(options.sessionKey.value)
    })
  }
  if (options.deliveryIdentity) {
    watch(options.deliveryIdentity, () => {
      if (options.connectionState?.value !== 'connected') return
      void hydratePendingQueue(options.sessionKey.value)
    })
  }
  watch(options.sessionKey, (sessionKey, previousSessionKey) => {
    if (sessionKey && sessionKey !== previousSessionKey) {
      void hydratePendingQueue(sessionKey)
    }
  })

  function supportsServerQueue(): boolean {
    return pendingInputQueue?.supportsQueue() === true
  }

  function supportsServerReorder(): boolean {
    return Boolean(
      supportsServerQueue()
      && pendingInputQueue?.supportsReorder()
      && (!options.connectionState || options.connectionState.value === 'connected'),
    )
  }

  function durableItem(item: ChatPendingItem): boolean {
    return Boolean(item.pendingInputId && options.pendingInputWal)
  }

  function identityAllowsDelivery(item: ChatPendingItem): boolean {
    return !item.pendingDeliveryIdentity || (
      options.connectionState?.value === 'connected'
      && item.pendingDeliveryIdentity === options.deliveryIdentity?.value
    )
  }

  function walRecordForItem(
    item: ChatPendingItem,
    state: PendingInputWalState = item.pendingPersistenceState || 'saving',
  ): PendingInputWalRecord {
    const now = Date.now()
    return {
      schemaVersion: 1,
      pendingInputId: item.pendingInputId!,
      sessionKey: item.ownerSessionKey || options.sessionKey.value,
      clientRequestId: item.pendingClientRequestId!,
      clientMessageId: item.pendingClientMessageId!,
      text: item.text,
      ...(item.turnCommand ? { turnCommand: copyTurnCommand(item.turnCommand) } : {}),
      ...(item.localPathReferences?.length ? { localPathReferences: copyLocalPathReferences(item.localPathReferences, item.text) } : {}),
      ...(item.retiredAnnotationInput ? { retiredAnnotationInput: true } : {}),
      ...(item.pageContext ? { pageContext: normalizePageContext(item.pageContext)! } : {}),
      ...(item.selectedSkills?.length ? { selectedSkills: copySelectedSkills(item.selectedSkills) } : {}),
      ...(item.draftIds?.length
        ? { draftIds: normalizeAnnotationDraftIds(item.draftIds) }
        : {}),
      attachments: (item.attachments || []).map(snapshotAttachment),
      intent: item.intent,
      ...(item.confirmedPlainText ? { confirmedPlainText: true } : {}),
      ...(item.ownerRequestId ? { ownerRequestId: item.ownerRequestId } : {}),
      state,
      mayHaveServerCopy: item.pendingMayHaveServerCopy === true,
      ...(item.pendingDeliveryIdentity ? { deliveryIdentity: item.pendingDeliveryIdentity } : {}),
      ...(item.pendingRetainAfterCancel ? { retainAfterCancel: true } : {}),
      ...(item.pendingRequestFingerprint
        ? { requestFingerprint: item.pendingRequestFingerprint }
        : {}),
      ...(item.pendingServerRevision
        ? { serverRevision: item.pendingServerRevision }
        : {}),
      ...(Number.isSafeInteger(item.pendingPosition)
        ? { position: item.pendingPosition }
        : {}),
      ...(Number.isSafeInteger(item.pendingWalRevision)
        ? { walRevision: item.pendingWalRevision }
        : {}),
      createdAt: Number(item.pendingCreatedAt) || now,
      updatedAt: now,
    }
  }

  function itemFromWalRecord(record: PendingInputWalRecord): ChatPendingItem {
    const mayHaveServerCopy = typeof record.mayHaveServerCopy === 'boolean'
      ? record.mayHaveServerCopy
      // Older clients downgraded an ambiguous `saving` row to `local_only`
      // when they met an older Gateway. No legacy state can therefore prove
      // that an enqueue never committed; only a newly persisted false bit can.
      : true
    const item = {
      pendingUiId: record.pendingInputId,
      text: record.text,
      ...(record.turnCommand ? { turnCommand: copyTurnCommand(record.turnCommand) } : {}),
      ...(record.localPathReferences?.length ? { localPathReferences: copyLocalPathReferences(record.localPathReferences, record.text) } : {}),
      ...((record.retiredAnnotationInput || record.promptAnnotationIds?.length)
        ? { retiredAnnotationInput: true } : {}),
      ...(record.pageContext ? { pageContext: normalizePageContext(record.pageContext)! } : {}),
      ...(record.selectedSkills?.length ? { selectedSkills: copySelectedSkills(record.selectedSkills) } : {}),
      ...(normalizeAnnotationDraftIds(record.draftIds).length
        ? { draftIds: normalizeAnnotationDraftIds(record.draftIds) }
        : {}),
      attachments: record.attachments.map(attachment => parkedQueues.restoreAttachment(snapshotAttachment(attachment))),
      intent: record.intent,
      ...(record.confirmedPlainText ? { confirmedPlainText: true } : {}),
      ownerSessionKey: record.sessionKey,
      ...(record.ownerRequestId ? { ownerRequestId: record.ownerRequestId } : {}),
      pendingInputId: record.pendingInputId,
      pendingClientRequestId: record.clientRequestId,
      pendingClientMessageId: record.clientMessageId,
      pendingPersistenceState: record.state,
      pendingMayHaveServerCopy: mayHaveServerCopy,
      ...(record.deliveryIdentity ? { pendingDeliveryIdentity: record.deliveryIdentity } : {}),
      ...(record.retainAfterCancel ? { pendingRetainAfterCancel: true } : {}),
      ...(record.requestFingerprint
        ? { pendingRequestFingerprint: record.requestFingerprint }
        : {}),
      ...(record.serverRevision
        ? { pendingServerRevision: record.serverRevision }
        : {}),
      ...(Number.isSafeInteger(record.position)
        ? { pendingPosition: record.position }
        : {}),
      pendingWalRevision: record.walRevision ?? 1,
      pendingCreatedAt: record.createdAt,
    } as ChatPendingItem
    parkedQueues.rememberCommitted(item, parkedQueues.snapshotForCommit(item))
    return item
  }

  function removedIdentity(sessionKey: string, pendingInputId: string): string {
    return `${sessionKey}\u0000${pendingInputId}`
  }

  function rememberRemoval(sessionKey: string, pendingInputId: string) {
    const identity = removedIdentity(sessionKey, pendingInputId)
    if (removedIdentities.has(identity)) return
    removedIdentities.add(identity)
    removedIdentityOrder.push(identity)
    while (removedIdentityOrder.length > MAX_REMOVAL_TOMBSTONES) {
      const expired = removedIdentityOrder.shift()
      if (expired) removedIdentities.delete(expired)
    }
  }

  function wasRemoved(sessionKey: string, pendingInputId: string): boolean {
    return removedIdentities.has(removedIdentity(sessionKey, pendingInputId))
  }

  function forgetRemoval(sessionKey: string, pendingInputId: string) {
    removedIdentities.delete(removedIdentity(sessionKey, pendingInputId))
  }

  function removePendingIdentity(sessionKey: string, pendingInputId: string) {
    if (options.sessionKey.value === sessionKey) {
      pendingQueue.value = pendingQueue.value.filter(item => (
        item.pendingInputId !== pendingInputId
      ))
    }
    const parked = parkedQueues.get(sessionKey)
    if (parked) {
      const retained = parked.filter(item => item.pendingInputId !== pendingInputId)
      if (retained.length > 0) parkedQueues.set(sessionKey, retained)
      else parkedQueues.delete(sessionKey)
    }
  }

  async function cancelServerIdentity(sessionKey: string, pendingInputId: string) {
    if (!supportsServerQueue()) return
    await pendingInputQueue!.cancel({
      key: sessionKey,
      pendingInputId,
    })
  }

  function broadcastChange(
    sessionKey: string,
    pendingInputId?: string,
    action: 'changed' | 'removed' = 'changed',
  ) {
    try {
      broadcast?.postMessage({ sessionKey, pendingInputId, action })
    } catch {}
  }

  async function writeWalItem(
    item: ChatPendingItem,
    state: PendingInputWalState = item.pendingPersistenceState || 'saving',
    publishStateAfterCommit = false,
  ): Promise<void> {
    if (!options.pendingInputWal || !item.pendingInputId) return
    // Mutate through the reactive array proxy when this item is mounted. New
    // durable items are first created as plain objects, and mutating only that
    // raw reference would not invalidate computed delivery barriers or UI.
    const trackedItem = pendingQueue.value.find(candidate => (
      candidate.pendingInputId === item.pendingInputId
    )) || item
    const previousWalRevision = trackedItem.pendingWalRevision
    const writeRevision = (previousWalRevision ?? 0) + 1
    if (!publishStateAfterCommit) trackedItem.pendingPersistenceState = state
    trackedItem.pendingWalRevision = writeRevision
    const cacheSnapshot = parkedQueues.snapshotForCommit({ ...trackedItem, pendingPersistenceState: state })
    try {
      await options.pendingInputWal.put(walRecordForItem(trackedItem, state))
      if (publishStateAfterCommit && trackedItem.pendingWalRevision === writeRevision) {
        trackedItem.pendingPersistenceState = state
      }
      parkedQueues.rememberCommitted(trackedItem, cacheSnapshot)
    } catch (error) {
      trackedItem.pendingWalRevision = previousWalRevision
      throw error
    }
  }

  function ordinaryDurableItem(item: ChatPendingItem): boolean {
    return Boolean(
      item.pendingInputId
      && !item.steerAttempt
      && !item.deliveryState,
    )
  }

  function sortOrdinaryPendingItems() {
    const ordinary = pendingQueue.value
      .filter(ordinaryDurableItem)
      .sort((left, right) => (
        (left.pendingPosition ?? Number.MAX_SAFE_INTEGER)
        - (right.pendingPosition ?? Number.MAX_SAFE_INTEGER)
        || (left.pendingCreatedAt ?? 0) - (right.pendingCreatedAt ?? 0)
        || String(left.pendingInputId).localeCompare(String(right.pendingInputId))
      ))
    let ordinaryIndex = 0
    pendingQueue.value = pendingQueue.value.map(item => (
      ordinaryDurableItem(item) ? ordinary[ordinaryIndex++]! : item
    ))
  }

  function pendingQueueFailure(error: unknown): PendingInputQueueError | null {
    return error instanceof PendingInputQueueError ? error : null
  }

  function durableAttachmentMetadata(attachment: Attachment): Attachment {
    if (attachment.kind === 'workspace') return { ...snapshotAttachment(attachment), file: undefined, durable_material: true }
    return {
      kind: 'staged',
      local_id: attachment.local_id,
      name: attachment.name,
      mime: attachment.mime,
      ...(typeof attachment.size === 'number' ? { size: attachment.size } : {}),
      ...(attachment.origin ? { origin: attachment.origin } : {}),
      durable_material: true,
    }
  }

  function attachmentsFromServerItem(serverItem: PendingInputServerItem): Attachment[] {
    const imported: Attachment[] = (serverItem.attachments || []).map((attachment, index) => ({
      kind: 'staged' as const,
      local_id: -(index + 1),
      name: attachment.name,
      mime: attachment.mime,
      durable_material: true as const,
      ...(attachment.origin ? { origin: attachment.origin } : {}),
      ...(typeof attachment.size === 'number' ? { size: attachment.size } : {}),
    }))
    return [...imported, ...(serverItem.workspaceFiles || []).map((ref, index): Attachment => ({
      kind: 'workspace', local_id: -(imported.length + index + 1), name: ref.name,
      mime: ref.mime, size: ref.size, workspaceFile: { ...ref }, durable_material: true,
    }))]
  }

  async function ensureServerStaged(item: ChatPendingItem): Promise<void> {
    const pendingInputId = item.pendingInputId
    if (!pendingInputId || !options.pendingInputWal) return
    if (locallyCreatingIds.has(pendingInputId)) return
    if (!identityAllowsDelivery(item)) return
    // A definite rejection requires an explicit edit/retry. Reconnecting is
    // not authorization to repeat a denied offline submission indefinitely.
    if (item.pendingDeliveryIdentity && item.pendingPersistenceState === 'retryable') return
    if (item.ownerRequestId || item.retiredAnnotationInput) return
    if (
      item.pendingPersistenceState === 'cancelling'
      || item.pendingRetainAfterCancel === true
    ) return
    const sessionKey = item.ownerSessionKey || options.sessionKey.value
    if (wasRemoved(sessionKey, pendingInputId)) return
    const existing = stagingOperations.get(pendingInputId)
    if (existing) return existing
    const previouslyMayHaveServerCopy = item.pendingMayHaveServerCopy === true
    const operation = (async () => {
      if (wasRemoved(sessionKey, pendingInputId)) return
      if (!supportsServerQueue()) {
        await writeWalItem(item, 'local_only')
        return
      }
      let refreshedLostUpload = false
      try {
        try {
          if (item.pageContext != null) assertPageContextWithinLimits(item.pageContext)
        } catch (error) {
          // Hydration retries staging. An unchanged invalid row must not write
          // another WAL revision and trigger hydration indefinitely.
          if (item.pendingPersistenceState === 'retryable') return
          throw new PendingInputQueueError('invalid', error instanceof Error ? error.message : 'Invalid page context.', false)
        }
        while (true) {
          if (!identityAllowsDelivery(item)) return
          if (wasRemoved(sessionKey, pendingInputId)) return
          if (item.turnCommand && !await options.supportsTurnCommand?.(item.turnCommand)) {
            await writeWalItem(item, 'local_only')
            return
          }
          if (item.attachments.length > 0 && options.prepareAttachmentsForSend) {
            const preparationIsCurrent = () => (
              (!item.pendingDeliveryIdentity || (
                options.sessionKey.value === sessionKey && identityAllowsDelivery(item)
              ))
              && pendingQueue.value.some(candidate => candidate.pendingInputId === pendingInputId)
            )
            const ready = await options.prepareAttachmentsForSend({
              attachments: item.attachments,
              isCurrent: preparationIsCurrent,
            })
            // A cancelled authority/session lease is not a server rejection.
            // Leave the original local WAL intact for its proven owner.
            if (!preparationIsCurrent()) return
            if (!ready) {
              await writeWalItem(item, 'retryable')
              options.onPendingPersistenceError?.('server_rejected')
              return
            }
            if (!identityAllowsDelivery(item)) return
            // Persist refreshed upload UUIDs before the request can become
            // ambiguous. A reload then retries the same material snapshot.
            await writeWalItem(item, 'saving')
          }
          if (wasRemoved(sessionKey, pendingInputId)) return
          const sendable = item.attachments.filter(isSendableAttachment)
          if (sendable.length !== item.attachments.length) {
            await writeWalItem(item, 'retryable')
            options.onPendingPersistenceError?.('server_rejected')
            return
          }
          try {
            const queuedText = item.text.trim()
            const literalSlashEscape = queuedText.startsWith('//')
            const providerMessage = literalSlashEscape
              ? queuedText.slice(1)
              : queuedText
            // Write the cross-boundary provenance before sending.  A crash or
            // lost ACK can then distinguish this identity from a genuinely
            // IndexedDB-only draft when the next Gateway is older/offline.
            item.pendingMayHaveServerCopy = true
            await writeWalItem(item, 'saving')
            if (!identityAllowsDelivery(item)) {
              if (item.pendingDeliveryIdentity && !previouslyMayHaveServerCopy) {
                item.pendingMayHaveServerCopy = false
                await writeWalItem(item, 'local_only')
              }
              return
            }
            if (item.turnCommand && !await options.supportsTurnCommand?.(item.turnCommand)) {
              // The RPC has not started. Retain an older ambiguous attempt,
              // but do not claim a server copy for this revoked admission.
              item.pendingMayHaveServerCopy = previouslyMayHaveServerCopy
              await writeWalItem(item, 'local_only')
              return
            }
            if (!identityAllowsDelivery(item) || wasRemoved(sessionKey, pendingInputId)) return
            const response = await pendingInputQueue!.enqueue({
                key: item.ownerSessionKey || options.sessionKey.value,
                pendingInputId,
                clientRequestId: item.pendingClientRequestId,
                clientMessageId: item.pendingClientMessageId,
                message: providerMessage || item.pageContext?.annotations?.map(item => item.text).join('\n') || 'Describe these attachments',
                ...(item.turnCommand ? { turnCommand: copyTurnCommand(item.turnCommand) } : {}),
                ...serializeChatFiles(sendable),
                ...(item.pageContext ? { pageContext: item.pageContext } : {}),
                ...(item.selectedSkills?.length ? { selectedSkills: copySelectedSkills(item.selectedSkills) } : {}),
                ...(item.localPathReferences?.length ? { localPathReferences: copyLocalPathReferences(item.localPathReferences, item.text) } : {}),
                ...(item.confirmedPlainText ? { confirmedPlainText: true } : {}),
                ...(sendable.length > 0 || literalSlashEscape || Boolean(item.pageContext?.annotations?.length)
                  ? { displayText: queuedText }
                  : {}),
                ...(item.intent ? { intent: item.intent } : {}),
                ...(Number.isSafeInteger(item.pendingPosition)
                  ? { position: item.pendingPosition }
                  : {}),
              })
            if (wasRemoved(sessionKey, pendingInputId)) {
              // A peer may cancel while this enqueue response is in flight.
              // Cancel again after the ACK so an enqueue that committed after
              // the first tombstone cannot resurrect the draft server-side.
              await cancelServerIdentity(sessionKey, pendingInputId).catch(() => {})
              await options.pendingInputWal!.delete(pendingInputId).catch(() => {})
              return
            }
            const fingerprint = response.requestFingerprint
            const revision = response.revision
            if (typeof fingerprint !== 'string' || !fingerprint) {
              throw new Error('Gateway returned an invalid pending-input acknowledgement')
            }
            item.pendingRequestFingerprint = fingerprint
            item.pendingServerRevision = typeof revision === 'number' ? revision : 1
            item.pendingPosition = typeof response.position === 'number'
              ? response.position
              : item.pendingPosition
            // The server ACK proves the session material store owns the bytes.
            // Drop base64, File objects and expiring upload capabilities from
            // IndexedDB; dispatch now needs only the stable pending identity.
            item.attachments = item.attachments.map(durableAttachmentMetadata)
            await writeWalItem(item, 'staged')
            flushDeferredPendingDrain()
            return
          } catch (error) {
            const kind = pendingQueueFailure(error)?.kind
            if (
              !refreshedLostUpload
              && options.prepareAttachmentsForSend
              && (kind === 'attachment-expired' || kind === 'attachment-lost')
              && item.attachments.some(attachment => attachment.kind === 'staged' && attachment.file)
            ) {
              refreshedLostUpload = true
              for (const attachment of item.attachments) {
                if (attachment.kind === 'staged' && attachment.file) {
                  attachment.expires_at = 0
                }
              }
              continue
            }
            throw error
          }
        }
      } catch (error) {
        const failure = pendingQueueFailure(error)
        if (
          failure?.kind === 'cancelled'
          || failure?.kind === 'already-dispatched'
        ) {
          // A peer or an earlier crashed tab already committed the durable
          // terminal outcome. Treat that server tombstone as authoritative
          // even when this tab missed the BroadcastChannel notification while
          // its enqueue result was ambiguous.
          rememberRemoval(sessionKey, pendingInputId)
          await options.pendingInputWal!.delete(pendingInputId).catch(() => {})
          removePendingIdentity(sessionKey, pendingInputId)
          broadcastChange(sessionKey, pendingInputId, 'removed')
          return
        }
        if (failure?.kind === 'unsupported') {
          await writeWalItem(item, 'local_only')
          flushDeferredPendingDrain()
          return
        }
        if (failure?.accepted === false) {
          // This attempt did not commit. Preserve any earlier ambiguous
          // attempt, but a first definite rejection remains locally owned.
          if (item.pendingDeliveryIdentity) {
            item.pendingMayHaveServerCopy = previouslyMayHaveServerCopy
          }
          await writeWalItem(item, 'retryable').catch(() => {})
          options.onPendingPersistenceError?.('server_rejected')
          return
        }
        // Unknown transport results deliberately remain "saving". Reconnect,
        // hydrate, or another tab retries this exact identity byte-for-byte.
        await writeWalItem(item, 'saving').catch(() => {})
      }
    })().finally(() => {
      stagingOperations.delete(pendingInputId)
      parkedQueues.trim()
    })
    stagingOperations.set(pendingInputId, operation)
    return operation
  }

  function mergeWalRecords(records: PendingInputWalRecord[], sessionKey: string) {
    const existingById = new Map(
      pendingQueue.value
        .filter(item => item.pendingInputId)
        .map(item => [item.pendingInputId!, item]),
    )
    for (const record of records) {
      const existing = existingById.get(record.pendingInputId)
      if (existing && record.retainAfterCancel === true) {
        Object.assign(existing, itemFromWalRecord(record))
        delete existing.deliveryState
        delete existing.pendingRequestFingerprint
        delete existing.pendingServerRevision
        delete existing.pendingPosition
        continue
      }
      if (
        record.sessionKey !== sessionKey
        || existing
        || wasRemoved(sessionKey, record.pendingInputId)
      ) continue
      const added = itemFromWalRecord(record)
      pendingQueue.value.push(added)
      existingById.set(record.pendingInputId, added)
    }
    sortOrdinaryPendingItems()
  }

  async function hydratePendingQueue(sessionKey = options.sessionKey.value): Promise<void> {
    const wal = options.pendingInputWal
    if (!wal || !sessionKey || disposed) return
    const reorder = pendingReorders.get(reorderOwnerKey(sessionKey))
    if (reorder) {
      reorder.deferredHydrate = true
      // Unknown server outcomes stay blocked while hidden. A return/reconnect
      // may reconcile that same owner, never retry the reorder or dispatch it.
      if (reorder.started && !reorder.commit && reorder.mode === 'server') {
        reorder.commit = recoverServerReorder(reorder).then(recovered => {
          if (recovered) finishPendingReorder(reorder)
        }).finally(() => { reorder.commit = undefined })
      }
      return
    }
    const generation = ++hydrateGeneration
    const hydrationIdentity = options.deliveryIdentity?.value ?? null
    const hydrationIsCurrent = () => !disposed
      && generation === hydrateGeneration
      && options.sessionKey.value === sessionKey
      && (options.deliveryIdentity?.value ?? null) === hydrationIdentity
    const serverHydrationIsCurrent = () => hydrationIsCurrent()
      && (!options.connectionState || options.connectionState.value === 'connected')
      && (!options.deliveryIdentity || hydrationIdentity !== null)
    const resumeHydratedOfflineDrafts = () => {
      // Initial mount and session navigation can finish their readiness events
      // before IndexedDB resolves. Hydration owns this signal too; it must not
      // depend on a later connection/identity change that may never happen.
      if (serverHydrationIsCurrent() && pendingQueue.value.some(item => (
        item.ownerSessionKey === sessionKey
        && item.pendingDeliveryIdentity
        && identityAllowsDelivery(item)
      ))) schedulePendingDrainAfterTerminal()
    }
    let records: PendingInputWalRecord[]
    try {
      records = await wal.list(sessionKey)
    } catch {
      options.onPendingPersistenceError?.('wal_failed')
      return
    }
    if (!hydrationIsCurrent()) return
    mergeWalRecords(records, sessionKey)
    const walIds = new Set(records.map(record => record.pendingInputId))
    // Disconnected hydration is local-only. In particular, do not advertise an
    // enqueue as ambiguous before it could have crossed the transport boundary.
    if (!serverHydrationIsCurrent()) return

    if (!supportsServerQueue()) {
      for (const item of [...pendingQueue.value]) {
        if (!serverHydrationIsCurrent()) return
        if (!durableItem(item) || item.ownerSessionKey !== sessionKey) continue
        if (!identityAllowsDelivery(item)) continue
        if (item.pendingDeliveryIdentity && item.pendingPersistenceState === 'retryable') continue
        const pendingInputId = item.pendingInputId!
        // A snapshot can race the WAL write and the enqueue itself. Keep an
        // in-flight/saving row visible until its owner settles; otherwise an
        // empty list response would tombstone a perfectly valid local item.
        const saving = item.pendingPersistenceState === 'saving'
        const stagingInFlight = stagingOperations.has(pendingInputId)
        if (
          !walIds.has(pendingInputId)
          && !locallyCreatingIds.has(pendingInputId)
          && !saving
          && !stagingInFlight
        ) {
          rememberRemoval(sessionKey, pendingInputId)
          removePendingIdentity(sessionKey, pendingInputId)
          continue
        }
        // A cancellation WAL is a durable delete intent, never a draft to
        // downgrade or re-enqueue. Keep it intact until a queue-capable
        // Gateway can accept the idempotent tombstone.
        if (
          item.pendingPersistenceState === 'cancelling'
          || item.pendingRetainAfterCancel === true
        ) continue
        if (item.pendingPersistenceState !== 'local_only') {
          void writeWalItem(item, 'local_only')
        }
      }
      resumeHydratedOfflineDrafts()
      return
    }

    // Cancellation does not depend on list reconciliation. Retry it as soon
    // as the capability is available so a failing/stale list response can
    // never turn a durable delete intent back into an enqueue attempt.
    for (const item of [...pendingQueue.value]) {
      if (!serverHydrationIsCurrent()) return
      if (
        durableItem(item)
        && item.ownerSessionKey === sessionKey
        && item.pendingPersistenceState === 'cancelling'
      ) void retryCancellingItem(item)
    }

    try {
      const response = { items: await pendingInputQueue!.list(sessionKey) }
      if (!serverHydrationIsCurrent()) return
      const serverItems = Array.isArray(response.items) ? response.items : []
      const serverIds = new Set<string>()
      for (const serverItem of serverItems) {
        if (!serverHydrationIsCurrent()) return
        const pendingInputId = serverItem.pendingInputId
        const clientRequestId = serverItem.clientRequestId
        const clientMessageId = serverItem.clientMessageId
        if (wasRemoved(sessionKey, pendingInputId)) {
          void cancelServerIdentity(sessionKey, pendingInputId).catch(() => {})
          continue
        }
        serverIds.add(pendingInputId)
        const serverAttachments = attachmentsFromServerItem(serverItem)
        let item = pendingQueue.value.find(candidate => (
          candidate.pendingInputId === pendingInputId
        ))
        if (item && !identityAllowsDelivery(item)) continue
        if (!item) {
          item = {
            pendingUiId: pendingInputId,
            ...(serverItem.turnCommand ? { turnCommand: copyTurnCommand(serverItem.turnCommand) } : {}),
            text: typeof serverItem.displayText === 'string'
              ? serverItem.displayText
              : serverItem.message || '',
            attachments: serverAttachments,
            ...(serverItem.selectedSkills?.length ? { selectedSkills: copySelectedSkills(serverItem.selectedSkills) } : {}),
            ...(serverItem.localPathReferences?.length ? { localPathReferences: copyLocalPathReferences(serverItem.localPathReferences, serverItem.displayText ?? serverItem.message) } : {}),
            intent: typeof serverItem.intent === 'string' ? serverItem.intent : null,
            ...(normalizePageContext(serverItem.pageContext)
              ? { pageContext: normalizePageContext(serverItem.pageContext)! } : {}),
            ...(serverItem.confirmedPlainText === true ? { confirmedPlainText: true } : {}),
            ownerSessionKey: sessionKey,
            pendingInputId,
            pendingClientRequestId: clientRequestId,
            pendingClientMessageId: clientMessageId,
            ...(hydrationIdentity ? { pendingDeliveryIdentity: hydrationIdentity } : {}),
          }
          pendingQueue.value.push(item)
        }
        if (item.pendingPersistenceState === 'cancelling') {
          // The local delete intent wins over a stale server list row. Do not
          // replace its payload/attachments or transition it back to staged;
          // retry only the same idempotent cancellation.
          void retryCancellingItem(item)
          continue
        }
        if (item.selectedSkills?.length && !sameSelectedSkills(item.selectedSkills, serverItem.selectedSkills)) {
          await writeWalItem(item, 'retryable')
          options.onPendingPersistenceError?.('server_rejected')
          continue
        }
        if (JSON.stringify(item.turnCommand ?? null) !== JSON.stringify(serverItem.turnCommand ?? null)) {
          await writeWalItem(item, 'retryable')
          options.onPendingPersistenceError?.('server_rejected')
          continue
        }
        if (Array.isArray(serverItem.attachments)) {
          // A list response is also the authoritative ACK for an enqueue whose
          // transport response was lost. Replace the WAL's File/base64/upload
          // snapshot with safe server-owned metadata before marking it staged.
          item.attachments = serverAttachments
        }
        if (serverItem.selectedSkills) item.selectedSkills = copySelectedSkills(serverItem.selectedSkills)
        if (serverItem.localPathReferences) item.localPathReferences = copyLocalPathReferences(serverItem.localPathReferences, item.text)
        const serverPageContext = normalizePageContext(serverItem.pageContext)
        if (serverPageContext) item.pageContext = serverPageContext
        item.pendingRequestFingerprint = serverItem.requestFingerprint
        item.pendingServerRevision = typeof serverItem.revision === 'number'
          ? serverItem.revision
          : 1
        item.pendingPosition = typeof serverItem.position === 'number'
          ? serverItem.position
          : item.pendingPosition
        item.pendingMayHaveServerCopy = true
        await writeWalItem(item, 'staged')
        if (!serverHydrationIsCurrent()) return
      }

      sortOrdinaryPendingItems()

      for (const item of [...pendingQueue.value]) {
        if (!serverHydrationIsCurrent()) return
        if (!durableItem(item) || item.ownerSessionKey !== sessionKey) continue
        if (!identityAllowsDelivery(item)) continue
        if (serverIds.has(item.pendingInputId!)) continue
        const pendingInputId = item.pendingInputId!
        // The list snapshot may have started before the WAL write or enqueue
        // completed. Preserve an in-flight row until its owner settles.
        const saving = item.pendingPersistenceState === 'saving'
        const stagingInFlight = stagingOperations.has(pendingInputId)
        if (
          !walIds.has(pendingInputId)
          && !locallyCreatingIds.has(pendingInputId)
          && !saving
          && !stagingInFlight
        ) {
          rememberRemoval(sessionKey, pendingInputId)
          removePendingIdentity(sessionKey, pendingInputId)
          continue
        }
        if (item.pendingPersistenceState === 'cancelling') {
          void retryCancellingItem(item)
          continue
        }
        if (item.pendingRetainAfterCancel === true) continue
        if (item.pendingPersistenceState === 'staged') {
          // Another tab either cancelled or dispatched the server row. Both
          // outcomes are terminal for this WAL entry.
          await wal.delete(item.pendingInputId!)
          if (!serverHydrationIsCurrent()) return
          const index = pendingQueue.value.indexOf(item)
          if (index >= 0) pendingQueue.value.splice(index, 1)
          continue
        }
        // This also upgrades IndexedDB-only rows created against an older
        // Gateway once a compatible Gateway is available.
        void ensureServerStaged(item)
      }
      resumeHydratedOfflineDrafts()
    } catch {
      // Server reconciliation is best effort; IndexedDB remains authoritative
      // until the next connected hydrate.
    }
  }

  if (broadcast) {
    broadcast.onmessage = event => {
      refreshQueuePolicy()
      const message = event.data as PendingQueueBroadcastMessage | null
      const sessionKey = typeof message?.sessionKey === 'string' ? message.sessionKey : ''
      const pendingInputId = typeof message?.pendingInputId === 'string'
        ? message.pendingInputId
        : ''
      if (!sessionKey) return
      if (message?.action === 'removed' && pendingInputId) {
        rememberRemoval(sessionKey, pendingInputId)
        removePendingIdentity(sessionKey, pendingInputId)
        void options.pendingInputWal?.delete(pendingInputId).catch(() => {})
        // Idempotently race any peer enqueue whose request was already in
        // flight when the cancellation tombstone arrived.
        void cancelServerIdentity(sessionKey, pendingInputId).catch(() => {})
        return
      }
      if (sessionKey === options.sessionKey.value) {
        void hydratePendingQueue(sessionKey)
      }
    }
  }
  if (options.pendingInputWal) void hydratePendingQueue()

  function resolveOwnerRequestId(owner?: PendingQueueOwner): string | undefined {
    if (owner?.ownerRequestId) return owner.ownerRequestId
    const context = options.ownerContext?.value
    return context?.sessionKey === options.sessionKey.value
      ? context.ownerRequestId
      : undefined
  }

  function enqueuePendingPayload(
    payload: PendingQueuePayload,
    owner?: PendingQueueOwner,
  ): boolean | Promise<boolean> {
    if (payload.deliveryIdentity && payload.deliveryIdentity !== options.deliveryIdentity?.value) {
      return false
    }
    if (ordinaryPendingCount.value >= MAX_PENDING) {
      console.warn(`Pending queue full (${MAX_PENDING})`)
      return false
    }
    // Clearing or otherwise transferring a composer payload is only safe once
    // IndexedDB owns the exact text, attachments and intent. An unavailable
    // WAL is a hard local persistence failure, not permission to create a
    // volatile queue item that disappears on refresh.
    if (!options.pendingInputWal) {
      options.onPendingPersistenceError?.('wal_failed')
      return false
    }
    const ownerRequestId = resolveOwnerRequestId(owner)
    const draftIds = normalizeAnnotationDraftIds(payload.draftIds)
    const item: ChatPendingItem = {
      pendingUiId: createClientRequestId(),
      text: payload.text,
      ...(payload.turnCommand ? { turnCommand: copyTurnCommand(payload.turnCommand) } : {}),
      ...(payload.localPathReferences?.length ? { localPathReferences: copyLocalPathReferences(payload.localPathReferences, payload.text) } : {}),
      ...(payload.pageContext ? { pageContext: normalizePageContext(payload.pageContext)! } : {}),
      ...(payload.selectedSkills?.length ? { selectedSkills: copySelectedSkills(payload.selectedSkills) } : {}),
      ...(draftIds.length ? { draftIds } : {}),
      attachments: (payload.attachments || []).map(snapshotAttachment),
      // Creation belongs to the in-flight first turn, never to its follow-ups.
      intent: payload.intent === 'new_chat' ? null : payload.intent ?? null,
      ...(payload.confirmedPlainText ? { confirmedPlainText: true } : {}),
      ...((payload.deliveryIdentity || (payload.turnCommand && options.deliveryIdentity?.value))
        ? { pendingDeliveryIdentity: payload.deliveryIdentity || options.deliveryIdentity!.value! } : {}),
      ownerSessionKey: options.sessionKey.value,
      ...(ownerRequestId ? { ownerRequestId } : {}),
    }
    const now = Date.now()
    item.pendingInputId = createClientRequestId()
    item.pendingClientRequestId = createClientRequestId()
    item.pendingClientMessageId = createClientMessageId()
    item.pendingPersistenceState = 'saving'
    item.pendingMayHaveServerCopy = false
    item.pendingCreatedAt = now
    item.pendingPosition = pendingQueue.value.filter(ordinaryDurableItem).length
    item.pendingWalRevision = 0
    pendingQueue.value.push(item)
    flushDeferredPendingDrain()
    locallyCreatingIds.add(item.pendingInputId)
    return (async () => {
      try {
        // "Saved locally" is a durability promise: the initial offline row
        // stays visibly saving until IndexedDB commits, including on close.
        await writeWalItem(
          item,
          item.pendingDeliveryIdentity ? 'local_only' : 'saving',
          Boolean(item.pendingDeliveryIdentity),
        )
      } catch {
        const index = pendingQueue.value.findIndex(candidate => (
          candidate.pendingInputId === item.pendingInputId
        ))
        if (index >= 0) pendingQueue.value.splice(index, 1)
        options.onPendingPersistenceError?.('wal_failed')
        return false
      } finally {
        locallyCreatingIds.delete(item.pendingInputId!)
        parkedQueues.trim()
      }
      broadcastChange(item.ownerSessionKey || options.sessionKey.value)
      void ensureServerStaged(item)
      return true
    })()
  }

  function enqueuePendingInput(
    text: string,
    owner?: PendingQueueOwner,
    enqueueOptions?: {
      turnCommand?: ProjectInitTurnCommand
      confirmedPlainText?: boolean
      draftIds?: readonly string[]
      selectedSkills?: SelectedSkillRef[]
      localPathReferences?: string[]
      pageContext?: ChatPageContext
      attachments?: Attachment[]
      deliveryIdentity?: string
    },
  ): boolean | Promise<boolean> {
    const commandText = localPathPresentation(text,
      enqueueOptions?.localPathReferences ?? options.localPathReferences?.value).text
    if (isControlInput(commandText) && !enqueueOptions?.confirmedPlainText && !enqueueOptions?.turnCommand) return false
    const composerSkills = copySelectedSkills(options.selectedSkills?.value)
    const composerPaths = copyLocalPathReferences(options.localPathReferences?.value, options.inputText.value)
    const composerText = options.inputText.value
    const composerAttachments = snapshotComposerAttachments(options.pendingAttachments.value)
    const composerIntent = options.pendingSessionIntent.value
    const composerSessionKey = options.sessionKey.value
    const composerRevision = options.composerRevision?.value
    const queued = enqueuePendingPayload({
      text,
      ...(enqueueOptions?.turnCommand ? { turnCommand: copyTurnCommand(enqueueOptions.turnCommand) } : {}),
      selectedSkills: copySelectedSkills(enqueueOptions?.selectedSkills ?? composerSkills),
      localPathReferences: copyLocalPathReferences(enqueueOptions?.localPathReferences ?? composerPaths, text),
      ...(enqueueOptions?.pageContext ? { pageContext: enqueueOptions.pageContext } : {}),
      ...(enqueueOptions?.draftIds?.length
        ? { draftIds: enqueueOptions.draftIds }
        : {}),
      attachments: enqueueOptions?.attachments ?? options.pendingAttachments.value,
      intent: composerIntent,
      ...(enqueueOptions?.confirmedPlainText ? { confirmedPlainText: true } : {}),
      ...(enqueueOptions?.deliveryIdentity ? { deliveryIdentity: enqueueOptions.deliveryIdentity } : {}),
    }, owner)
    const clearMatchingComposer = () => {
      if (
        options.sessionKey.value !== composerSessionKey
        || options.composerRevision?.value !== composerRevision
        || options.inputText.value !== composerText
        || !sameSelectedSkills(options.selectedSkills?.value, composerSkills)
        || JSON.stringify(options.localPathReferences?.value ?? []) !== JSON.stringify(composerPaths)
        || !composerAttachmentsMatch(options.pendingAttachments.value, composerAttachments)
        || options.pendingSessionIntent.value !== composerIntent
      ) return
      options.inputText.value = ''
      if (options.selectedSkills) options.selectedSkills.value = []
      options.pendingAttachments.value = []
      // First-turn acceptance consumes new_chat after its durable receipt.
      if (composerIntent !== 'new_chat') options.pendingSessionIntent.value = null
      options.autoResizeTextarea()
    }
    if (typeof queued === 'boolean') {
      if (queued) clearMatchingComposer()
      return queued
    }
    return queued.then(saved => {
      if (saved) clearMatchingComposer()
      return saved
    })
  }

  function enqueuePendingSteerAttempt(
    payload: PendingSteerPayload,
    owner?: PendingQueueOwner,
  ) {
    const request = snapshotSteerRequest(payload.request)
    const existing = pendingQueue.value.find(item => (
      item.steerAttempt?.request.client_request_id === request.client_request_id
    ))
    if (existing) return existing
    // A direct Steer needs a transport-owned pending row before its RPC can be
    // sent. Exactly one delivery barrier may own the extra transport slot;
    // ordinary queue capacity is accounted independently above.
    if (hasDeliveryBarrier.value) {
      console.warn(`Pending queue full (${MAX_PENDING})`)
      return null
    }
    const ownerRequestId = resolveOwnerRequestId(owner)
    const item: ChatPendingItem = {
      pendingUiId: request.client_request_id || createClientRequestId(),
      text: request.message,
      ...(request.localPathReferences?.length ? { localPathReferences: copyLocalPathReferences(request.localPathReferences, request.message) } : {}),
      attachments: [],
      intent: null,
      ownerSessionKey: options.sessionKey.value,
      ...(ownerRequestId ? { ownerRequestId } : {}),
      steerAttempt: {
        phase: payload.phase || 'submitting',
        request,
      },
    }
    pendingQueue.value.push(item)
    // Return the array-owned reactive proxy. Mutating the raw object after it
    // was inserted would bypass Vue's phase-change notifications in the UI.
    return pendingQueue.value[pendingQueue.value.length - 1] || item
  }

  async function forgetDurableItem(
    item: ChatPendingItem,
    action: 'changed' | 'removed' = 'changed',
  ): Promise<void> {
    if (!options.pendingInputWal || !item.pendingInputId) return
    const sessionKey = item.ownerSessionKey || options.sessionKey.value
    await options.pendingInputWal.delete(item.pendingInputId)
    if (action === 'removed') rememberRemoval(sessionKey, item.pendingInputId)
    broadcastChange(sessionKey, item.pendingInputId, action)
  }

  async function retainCancelledDraft(
    item: ChatPendingItem,
    sessionKey: string,
  ): Promise<boolean> {
    const previousMayHaveServerCopy = item.pendingMayHaveServerCopy
    const previousFingerprint = item.pendingRequestFingerprint
    const previousServerRevision = item.pendingServerRevision
    const previousPosition = item.pendingPosition
    item.pendingMayHaveServerCopy = false
    delete item.deliveryState
    delete item.pendingRequestFingerprint
    delete item.pendingServerRevision
    delete item.pendingPosition
    try {
      await writeWalItem(item, 'local_only')
      broadcastChange(sessionKey, item.pendingInputId, 'changed')
      return true
    } catch {
      item.pendingPersistenceState = 'cancelling'
      item.pendingMayHaveServerCopy = previousMayHaveServerCopy
      if (previousFingerprint) item.pendingRequestFingerprint = previousFingerprint
      if (previousServerRevision) item.pendingServerRevision = previousServerRevision
      if (Number.isSafeInteger(previousPosition)) item.pendingPosition = previousPosition
      broadcastChange(sessionKey, item.pendingInputId, 'changed')
      return false
    }
  }

  async function cancelDurableItem(
    item: ChatPendingItem,
    cancelOptions: PendingCancelOptions = {},
  ): Promise<boolean> {
    if (!durableItem(item)) return true
    const previousState = item.pendingPersistenceState || 'saving'
    const sessionKey = item.ownerSessionKey || options.sessionKey.value
    const retainAfterCancel = cancelOptions.retainAfterCancel === true
    if (item.pendingRetainAfterCancel === true && !retainAfterCancel) {
      try {
        await forgetDurableItem(item, 'removed')
        return true
      } catch {
        broadcastChange(sessionKey, item.pendingInputId, 'changed')
        return false
      }
    }
    const previousRetainAfterCancel = item.pendingRetainAfterCancel
    if (retainAfterCancel) item.pendingRetainAfterCancel = true
    else delete item.pendingRetainAfterCancel
    rememberRemoval(sessionKey, item.pendingInputId!)
    try {
      await writeWalItem(item, 'cancelling')
    } catch {
      // The delete intent never became durable, so the composer/queue must keep
      // owning the previous state. No cancellation RPC was sent.
      forgetRemoval(sessionKey, item.pendingInputId!)
      if (previousRetainAfterCancel) item.pendingRetainAfterCancel = true
      else delete item.pendingRetainAfterCancel
      await writeWalItem(item, previousState).catch(() => {})
      broadcastChange(sessionKey, item.pendingInputId, 'changed')
      return false
    }

    // A proven IndexedDB-only row can be forgotten immediately on an older
    // Gateway. Anything that may have crossed the network must retain its
    // cancelling WAL until a queue-capable Gateway can write the tombstone.
    if (
      !supportsServerQueue()
      || !identityAllowsDelivery(item)
      || (item.pendingDeliveryIdentity && !item.pendingMayHaveServerCopy)
    ) {
      if (item.pendingMayHaveServerCopy) {
        broadcastChange(sessionKey, item.pendingInputId, 'changed')
        return false
      }
      try {
        if (retainAfterCancel) return retainCancelledDraft(item, sessionKey)
        await forgetDurableItem(item, 'removed')
        return true
      } catch {
        forgetRemoval(sessionKey, item.pendingInputId!)
        await writeWalItem(item, previousState).catch(() => {})
        broadcastChange(sessionKey, item.pendingInputId, 'changed')
        return false
      }
    }

    try {
      // An enqueue ACK may be lost after the Gateway committed the row, leaving
      // the WAL in `saving`. Cancellation is idempotent, so every durable item
      // connected to a queue-capable Gateway must attempt the server tombstone
      // before its local WAL is removed. Otherwise a deleted chip can reappear
      // on the next hydrate.
      await pendingInputQueue!.cancel({
        key: item.ownerSessionKey || options.sessionKey.value,
        pendingInputId: item.pendingInputId!,
        ...(previousState === 'staged' && item.pendingServerRevision
          ? { expectedRevision: item.pendingServerRevision }
          : {}),
      })
      if (retainAfterCancel) return retainCancelledDraft(item, sessionKey)
      await forgetDurableItem(item, 'removed')
      return true
    } catch {
      // The RPC or local delete may have committed despite a lost response.
      // Preserve the durable delete intent and retry the same identity after
      // reconnect instead of making the item dispatchable again.
      broadcastChange(sessionKey, item.pendingInputId, 'changed')
      return false
    }
  }

  function retryCancellingItem(item: ChatPendingItem): Promise<boolean> {
    const pendingInputId = item.pendingInputId
    if (!pendingInputId || item.pendingPersistenceState !== 'cancelling') {
      return Promise.resolve(false)
    }
    const existing = cancellationOperations.get(pendingInputId)
    if (existing) return existing
    const operation = cancelDurableItem(item, {
      retainAfterCancel: item.pendingRetainAfterCancel === true,
    }).then(cancelled => {
      if (!cancelled) return false
      if (
        item.pendingPersistenceState === 'local_only'
        && item.pendingRetainAfterCancel === true
      ) return true
      removePendingIdentity(
        item.ownerSessionKey || options.sessionKey.value,
        pendingInputId,
      )
      return true
    }).finally(() => {
      cancellationOperations.delete(pendingInputId)
      parkedQueues.trim()
    })
    cancellationOperations.set(pendingInputId, operation)
    return operation
  }

  function pendingIndex(pendingUiId: string): number {
    return pendingQueue.value.findIndex(item => item.pendingUiId === pendingUiId)
  }

  function removePendingChip(pendingUiId: string) {
    const index = pendingIndex(pendingUiId)
    const item = pendingQueue.value[index]
    if (
      isReordering.value
      || !item
      || item.deliveryState === 'steering'
      || item.steerAttempt?.phase === 'submitting'
    ) return false
    if (durableItem(item)) {
      void cancelDurableItem(item).then(cancelled => {
        if (!cancelled) return
        const currentIndex = pendingQueue.value.indexOf(item)
        if (currentIndex >= 0) pendingQueue.value.splice(currentIndex, 1)
      })
      return true
    }
    pendingQueue.value.splice(index, 1)
    return true
  }

  function beginPendingDelivery(
    pendingUiId: string,
  ): ChatPendingItem | null {
    if (isReordering.value) return null
    const index = pendingIndex(pendingUiId)
    const item = pendingQueue.value[index]
    if (
      !item
      || !identityAllowsDelivery(item)
      || item.pendingRetainAfterCancel === true
      || item.retiredAnnotationInput
      || item.deliveryState === 'steering'
      || item.steerAttempt?.phase === 'submitting'
      || item.pendingPersistenceState === 'saving'
      || item.pendingPersistenceState === 'cancelling'
      || item.pendingPersistenceState === 'retryable'
    ) return null
    const otherDelivery = pendingQueue.value.find(
      candidate => candidate !== item && (candidate.deliveryState || candidate.steerAttempt),
    )
    if (otherDelivery) return null
    // This generic lease covers the small validation window before a queued
    // draft becomes a Steer. `steerDelivery.begin` clears it atomically when
    // the canonical attempt is installed.
    item.deliveryState = 'steering'
    return item
  }

  function settlePendingDelivery(item: ChatPendingItem, outcome: PendingDeliveryOutcome) {
    let container = pendingQueue.value
    let index = container.indexOf(item)
    if (index < 0) {
      for (const parked of parkedQueues.values()) {
        const parkedIndex = parked.indexOf(item)
        if (parkedIndex < 0) continue
        container = parked
        index = parkedIndex
        break
      }
    }
    // Explicit navigation intentionally discards the old queue. If that
    // happened while an RPC settled, there is no queue ownership left to
    // update.
    if (index < 0) return
    if (outcome === 'accepted') {
      container.splice(index, 1)
      void forgetDurableItem(item).catch(() => {
        // The accepted server receipt is authoritative. A failed local delete
        // is reconciled against the now-missing server row on next hydrate.
      })
      parkedQueues.trim()
      flushDeferredPendingDrain()
      return
    }
    if (outcome === 'deferred' && !item.steerAttempt) {
      item.deliveryState = undefined
      parkedQueues.trim()
      deferredDrainRequested = true
      flushDeferredPendingDrain()
      return
    }
    if (!item.steerAttempt) {
      item.deliveryState = outcome === 'retryable_failure' ? 'retryable' : undefined
    }
    parkedQueues.trim()
    flushDeferredPendingDrain()
  }

  function clearPendingQueue() {
    cancelPendingReorder()
    clearPendingDrainAfterTerminalTimer()
    for (const item of [...pendingQueue.value]) {
      if (
        item.deliveryState === 'steering'
        || item.steerAttempt?.phase === 'submitting'
      ) continue
      const index = pendingQueue.value.indexOf(item)
      if (index < 0) continue
      if (durableItem(item)) {
        void cancelDurableItem(item).then(cancelled => {
          if (!cancelled) return
          const currentIndex = pendingQueue.value.indexOf(item)
          if (currentIndex >= 0) pendingQueue.value.splice(currentIndex, 1)
        })
      } else {
        pendingQueue.value.splice(index, 1)
      }
    }
  }

  function switchPendingQueue(
    targetSessionKey: string,
    shouldCommit: () => boolean = () => true,
    _handoffSignal?: AbortSignal,
  ): void | Promise<void> {
    if (disposed || !shouldCommit()) return
    cancelPendingReorder()
    clearPendingDrainAfterTerminalTimer()
    const sourceSessionKey = options.sessionKey.value
    if (sourceSessionKey && pendingQueue.value.length > 0) {
      const existing = parkedQueues.get(sourceSessionKey) || []
      const existingIds = new Set(existing.map(item => item.pendingInputId).filter(Boolean))
      parkedQueues.set(sourceSessionKey, [
        ...existing,
        ...pendingQueue.value.filter(item => (
          !item.pendingInputId || !existingIds.has(item.pendingInputId)
        )),
      ])
    }
    const restored = parkedQueues.get(targetSessionKey) || []
    parkedQueues.delete(targetSessionKey)
    pendingQueue.value = restored
    parkedQueues.trim()
    nextTick(() => void hydratePendingQueue(targetSessionKey))
  }

  function applyAcceptedHandoffCommit(
    commit: AcceptedHandoffCommit,
    targetSessionKey: string,
    ownerRequestId: string,
  ) {
    const committedById = new Map(
      commit.records.map(record => [record.pendingInputId, itemFromWalRecord(record)]),
    )
    const migrated: ChatPendingItem[] = []
    const updateOwned = (items: ChatPendingItem[]) => items.flatMap(item => {
      if (item.ownerRequestId !== ownerRequestId) return [item]
      const committed = item.pendingInputId
        ? committedById.get(item.pendingInputId)
        : undefined
      if (!committed) return [item]
      Object.assign(item, committed)
      item.ownerRequestId = undefined
      parkedQueues.rememberCommitted(item, parkedQueues.snapshotForCommit(item))
      committedById.delete(committed.pendingInputId!)
      migrated.push(item)
      return []
    })
    pendingQueue.value = updateOwned(pendingQueue.value)
    // Updating the LRU cache reinserts keys; a live Map iterator would revisit them.
    for (const [sessionKey, items] of [...parkedQueues]) {
      const retained = updateOwned(items)
      if (retained.length > 0) parkedQueues.set(sessionKey, retained)
      else parkedQueues.delete(sessionKey)
    }
    const targetItems = parkedQueues.get(targetSessionKey) || []
    const targetIds = new Set(targetItems.map(item => item.pendingInputId).filter(Boolean))
    for (const committed of [...migrated, ...committedById.values()]) {
      if (!targetIds.has(committed.pendingInputId)) targetItems.push(committed)
    }
    if (targetItems.length > 0) parkedQueues.set(targetSessionKey, targetItems)
  }

  async function acceptDurableHandoff(
    sourceSessionKey: string,
    targetSessionKey: string,
    ownerRequestId: string,
    shouldApply: () => boolean = () => true,
    handoffSignal?: AbortSignal,
  ): Promise<boolean> {
    if (disposed || !options.pendingInputWal?.acceptHandoff) return false
    const deliveryIdentity = options.deliveryIdentity?.value || ''
    if (options.pendingInputWal.listHandoffs) {
      const records = await options.pendingInputWal.listHandoffs()
      if (disposed || !shouldApply()) return false
      if (!records.some(record => record.ownerRequestId === ownerRequestId)) return false
    }
    if (disposed || !shouldApply()) return false
    const sourceScope = { sessionKey: sourceSessionKey, deliveryIdentity }
    const targetScope = { sessionKey: targetSessionKey, deliveryIdentity }
    // The child must already be held before any row can move there. This also
    // covers a reload after the WAL commit but before its promise is resumed.
    const preparedPolicy = queuePolicy.beginHandoff(sourceScope, targetScope, ownerRequestId)
    refreshQueuePolicy()
    if (!preparedPolicy.persisted) {
      options.onPendingPersistenceError?.('pause_failed')
      throw new Error('Could not persist the pending queue handoff policy')
    }
    const commit = await options.pendingInputWal.acceptHandoff(
      ownerRequestId,
      targetSessionKey,
      shouldApply,
      handoffSignal,
    )
    if (!commit) return false
    const completedPolicy = queuePolicy.completeHandoff(sourceScope, targetScope, ownerRequestId)
    if (!completedPolicy.persisted) options.onPendingPersistenceError?.('pause_failed')
    // A WAL transaction already in progress may finish after page cleanup.
    // Its committed rows belong to the next queue owner; do not reconstruct
    // attachments or install them into this disposed page's cache.
    if (!disposed && shouldApply()) {
      refreshQueuePolicy()
      applyAcceptedHandoffCommit(commit, targetSessionKey, ownerRequestId)
    }
    return true
  }

  async function recoverPendingQueueHandoff(
    sourceSessionKey: string,
    targetSessionKey: string,
    ownerRequestId: string,
  ): Promise<void> {
    if (disposed || !sourceSessionKey || !targetSessionKey || !ownerRequestId) return
    const committed = await acceptDurableHandoff(sourceSessionKey, targetSessionKey, ownerRequestId)
    if (!committed || disposed) return
    if (options.sessionKey.value === targetSessionKey) {
      const restored = parkedQueues.get(targetSessionKey) || []
      parkedQueues.delete(targetSessionKey)
      pendingQueue.value = [...pendingQueue.value, ...restored]
      sortOrdinaryPendingItems()
      for (const item of pendingQueue.value) {
        if (item.ownerSessionKey === targetSessionKey) void ensureServerStaged(item)
      }
    }
    broadcastChange(sourceSessionKey)
    broadcastChange(targetSessionKey)
  }

  async function failPendingQueueHandoff(ownerRequestId: string): Promise<void> {
    const owned = [
      ...pendingQueue.value,
      ...[...parkedQueues.values()].flat(),
    ].filter(item => item.ownerRequestId === ownerRequestId && durableItem(item))
    await Promise.all(owned.map(item => writeWalItem(item, 'retryable').catch(() => {})))
    for (const item of owned) {
      broadcastChange(item.ownerSessionKey || options.sessionKey.value, item.pendingInputId)
    }
  }

  async function adoptPendingQueue(
    targetSessionKey: string,
    ownerRequestId: string,
    shouldCommit: () => boolean = () => true,
    handoffSignal?: AbortSignal,
  ) {
    if (disposed) return
    const reorderCommit = activeReorder()?.commit
    if (reorderCommit) await reorderCommit
    else cancelPendingReorder()
    if (disposed || !shouldCommit()) return
    const sourceSessionKey = options.sessionKey.value
    const durableCommitApplied = await acceptDurableHandoff(
      sourceSessionKey,
      targetSessionKey,
      ownerRequestId,
      shouldCommit,
      handoffSignal,
    )
    if (disposed || !shouldCommit()) return
    if (!durableCommitApplied && pendingQueue.value.some(item => (
      item.ownerSessionKey === sourceSessionKey && item.ownerRequestId === ownerRequestId
    ))) {
      const deliveryIdentity = options.deliveryIdentity?.value || ''
      const sourceScope = { sessionKey: sourceSessionKey, deliveryIdentity }
      const targetScope = { sessionKey: targetSessionKey, deliveryIdentity }
      queuePolicy.beginHandoff(sourceScope, targetScope, ownerRequestId)
      const policy = queuePolicy.completeHandoff(sourceScope, targetScope, ownerRequestId)
      refreshQueuePolicy()
      if (!policy.persisted) options.onPendingPersistenceError?.('pause_failed')
    }
    // The source queue still owns its terminal drain signal until the durable
    // handoff has committed and this epoch is current. Clearing it before the
    // await would strand A if IndexedDB failed or A→B was superseded by A.
    clearPendingDrainAfterTerminalTimer()
    const carried: ChatPendingItem[] = []
    const stayingVisible: ChatPendingItem[] = []
    for (const item of pendingQueue.value) {
      if (
        !durableCommitApplied
        && ownerRequestId
        && item.ownerSessionKey === sourceSessionKey
        && item.ownerRequestId === ownerRequestId
      ) {
        // Keep object identity: an in-flight explicit steer stores its
        // idempotent retry attempt against this exact queue item.
        item.ownerSessionKey = targetSessionKey
        item.ownerRequestId = undefined
        carried.push(item)
        if (durableItem(item)) {
          nextTick(() => {
            void writeWalItem(item, 'saving').then(() => ensureServerStaged(item))
          })
        }
      } else {
        stayingVisible.push(item)
      }
    }
    if (stayingVisible.length > 0) {
      parkedQueues.set(sourceSessionKey, [
        ...(parkedQueues.get(sourceSessionKey) || []),
        ...stayingVisible,
      ])
    }
    const targetItems = parkedQueues.get(targetSessionKey) || []
    parkedQueues.delete(targetSessionKey)
    pendingQueue.value = [...targetItems, ...carried]
    parkedQueues.trim()
    sortOrdinaryPendingItems()
    for (const item of pendingQueue.value) {
      if (item.ownerSessionKey === targetSessionKey) void ensureServerStaged(item)
    }
    broadcastChange(sourceSessionKey)
    broadcastChange(targetSessionKey)
    nextTick(() => void hydratePendingQueue(targetSessionKey))
  }

  function hasUneditablePendingAttachments(item: ChatPendingItem): boolean {
    return item.attachments.some(attachment => (
      attachment.durable_material
      || (item.pendingPersistenceState === 'staged'
        && attachment.kind === 'staged'
        && !attachment.file)
    ))
  }

  function composerOwnershipGuard(): () => boolean {
    const sessionKey = options.sessionKey.value
    const identity = options.deliveryIdentity?.value
    const revision = options.composerRevision?.value
    const text = options.inputText.value
    const paths = JSON.stringify(options.localPathReferences?.value ?? [])
    const skills = copySelectedSkills(options.selectedSkills?.value)
    const attachments = snapshotComposerAttachments(options.pendingAttachments.value)
    const intent = options.pendingSessionIntent.value
    return () => options.sessionKey.value === sessionKey
      && options.deliveryIdentity?.value === identity
      && options.composerRevision?.value === revision
      && options.inputText.value === text
      && JSON.stringify(options.localPathReferences?.value ?? []) === paths
      && sameSelectedSkills(options.selectedSkills?.value, skills)
      && composerAttachmentsMatch(options.pendingAttachments.value, attachments)
      && options.pendingSessionIntent.value === intent
  }

  function mergedSkills(items: readonly ChatPendingItem[]): SelectedSkillRef[] | null {
    const skills = copySelectedSkills(options.selectedSkills?.value)
    for (const item of items) {
      if (item.selectedSkills?.length && !options.selectedSkills) return null
      for (const ref of item.selectedSkills || []) {
        const prior = skills.find(skill => skill.name === ref.name)
        if (prior && !sameSelectedSkills([prior], [ref])) return null
        if (!prior) skills.push({ ...ref })
      }
    }
    return skills.length <= 16 ? skills : null
  }

  function restoreSkills(items: readonly ChatPendingItem[]): void {
    const skills = mergedSkills(items)
    if (skills && options.selectedSkills) options.selectedSkills.value = skills
  }

  function restoreInput(text: string, paths?: readonly string[]) {
    if (options.restoreInput) options.restoreInput(text, paths)
    else options.inputText.value = text
  }

  function restoreCombinedInput(inputs: { text: string; localPathReferences?: readonly string[] }[]) {
    // Preserve complete canonical text for clients without chip restoration.
    if (!options.restoreInput) {
      options.inputText.value = inputs.map(input => input.text).filter(Boolean).join('\n')
      return
    }
    const pieces = inputs.map(input => localPathPresentation(input.text, input.localPathReferences))
    const text = pieces.map(piece => piece.text).filter(Boolean).join('\n')
    const paths = pieces.flatMap(piece => piece.paths)
    restoreInput([text, ...paths].filter(Boolean).join('\n'), paths)
  }

  function currentComposerInput() {
    return { text: options.inputText.value, localPathReferences: options.localPathReferences?.value }
  }

  function canRestoreToComposer(item: ChatPendingItem): boolean {
    return mergedSkills([item]) !== null
      && (!item.ownerSessionKey || item.ownerSessionKey === options.sessionKey.value)
      && (!item.pendingDeliveryIdentity || item.pendingDeliveryIdentity === options.deliveryIdentity?.value)
  }

  async function restoreQueuedAnnotations(
    pendingUiId: string,
    restore: (item: ChatPendingItem) => void,
  ): Promise<boolean> {
    const item = pendingQueue.value.find(candidate => candidate.pendingUiId === pendingUiId)
    if (!item?.pageContext || item.deliveryState || item.steerAttempt
      || item.pendingPersistenceState === 'saving' || item.pendingPersistenceState === 'cancelling'
      || !canRestoreToComposer(item) || hasUneditablePendingAttachments(item)) return false
    const stillOwnsComposer = composerOwnershipGuard()
    const restoredAttachments = (item.attachments || []).map(attachment => (
      item.pendingPersistenceState === 'staged' && attachment.kind === 'staged' && attachment.file
        ? { ...attachment, expires_at: 0 }
        : attachment
    ))
    if (durableItem(item) && !await cancelDurableItem(item, { retainAfterCancel: true })) return false
    if (!stillOwnsComposer() || !canRestoreToComposer(item)
      || !pendingQueue.value.includes(item)) return false
    // Restore durable context first. A local storage failure leaves the cancelled
    // queue item available for another recovery attempt.
    restore(item)
    restoreSkills([item])
    restoreCombinedInput([item, currentComposerInput()])
    options.pendingAttachments.value = [...restoredAttachments, ...options.pendingAttachments.value]
    options.pendingSessionIntent.value = options.pendingSessionIntent.value || item.intent || null
    options.autoResizeTextarea()
    const index = pendingQueue.value.indexOf(item)
    if (index >= 0) pendingQueue.value.splice(index, 1)
    if (durableItem(item)) await forgetDurableItem(item, 'removed').catch(() => {})
    return true
  }

  async function cancelForComposer(
    item: ChatPendingItem,
    stillOwnsComposer: () => boolean,
    restore: () => void,
  ): Promise<void> {
    // Preserve an editable local copy until cancellation and editor ownership
    // are both proven. A route/account/draft change cannot discard or inject it.
    const cancelled = await cancelDurableItem(item, { retainAfterCancel: true })
    if (!cancelled || !stillOwnsComposer() || !canRestoreToComposer(item)) return
    const index = pendingQueue.value.indexOf(item)
    if (index >= 0) pendingQueue.value.splice(index, 1)
    restore()
    // The retained copy cannot auto-dispatch if cleanup fails; the composer
    // already owns the payload and an explicit future edit remains safe.
    await forgetDurableItem(item, 'removed').catch(() => {})
  }

  function editPendingItem(pendingUiId: string): boolean {
    const index = pendingIndex(pendingUiId)
    const item = pendingQueue.value[index]
    if (
      !item
      || !canRestoreToComposer(item)
      || item.deliveryState
      || item.steerAttempt
      // The text editor cannot reconstruct a frozen page selection. Keep the
      // complete queued context until it is sent or explicitly removed.
      || item.pageContext
      || item.pendingPersistenceState === 'saving'
      || item.pendingPersistenceState === 'cancelling'
      || hasUneditablePendingAttachments(item)
    ) return false
    const restore = () => {
      restoreSkills([item])
      restoreCombinedInput([item, currentComposerInput()])
      const restoredAttachments = (item.attachments || []).map(attachment => (
        item.pendingPersistenceState === 'staged'
        && attachment.kind === 'staged'
        && attachment.file
          ? { ...attachment, expires_at: 0 }
          : attachment
      ))
      options.pendingAttachments.value = [
        ...restoredAttachments,
        ...options.pendingAttachments.value,
      ]
      options.pendingSessionIntent.value = (
        item.intent || options.pendingSessionIntent.value
      )
      options.autoResizeTextarea()
    }
    if (durableItem(item)) {
      void cancelForComposer(item, composerOwnershipGuard(), restore)
      return true
    }
    pendingQueue.value.splice(index, 1)
    restore()
    return true
  }

  function popPendingTail() {
    // Explicit or ambiguous steer deliveries must retain
    // their own transport identity instead of being converted into a fresh
    // composer send.
    let tailIndex = pendingQueue.value.length - 1
    while (
      tailIndex >= 0
      && (
        pendingQueue.value[tailIndex]?.deliveryState
        || pendingQueue.value[tailIndex]?.steerAttempt
        || pendingQueue.value[tailIndex]?.pageContext
      )
    ) tailIndex--
    if (tailIndex < 0) return false
    const tail = pendingQueue.value[tailIndex]
    if (!tail || !canRestoreToComposer(tail)) return false
    if (hasUneditablePendingAttachments(tail)) return false
    if (durableItem(tail)) {
      void cancelForComposer(tail, composerOwnershipGuard(), () => {
        restoreSkills([tail])
        restoreInput(tail.text || '', tail.localPathReferences)
        options.pendingAttachments.value = tail.attachments || []
        options.pendingSessionIntent.value = tail.intent || null
        options.autoResizeTextarea()
      })
      return true
    }
    pendingQueue.value.splice(tailIndex, 1)
    restoreSkills([tail])
    restoreInput(tail.text || '', tail.localPathReferences)
    options.pendingAttachments.value = tail?.attachments || []
    options.pendingSessionIntent.value = tail?.intent || null
    options.autoResizeTextarea()
    return true
  }

  function popAllPendingIntoComposer(): boolean {
    cancelPendingReorder()
    clearPendingDrainAfterTerminalTimer()
    if (!options.hasComposer() || pendingQueue.value.length === 0) return false
    // Explicit or ambiguous steer deliveries stay queued;
    // only transport-free visible drafts can safely return to the composer.
    const visible = pendingQueue.value.filter(
      p => !p.deliveryState
        && !p.steerAttempt
        && !p.pageContext
        && canRestoreToComposer(p)
        && !hasUneditablePendingAttachments(p),
    )
    const retained = pendingQueue.value.filter(
      p => p.deliveryState
        || p.steerAttempt
        || p.pageContext
        || !canRestoreToComposer(p)
        || hasUneditablePendingAttachments(p),
    )
    if (visible.length === 0 || mergedSkills(visible) === null) return false
    const immediate = visible.filter(item => !durableItem(item))
    const durable = visible.filter(durableItem)
    const queuedAttachments = immediate.flatMap(p => p.attachments || [])
    const headIntent = immediate[0]?.intent
    const current = currentComposerInput()
    pendingQueue.value = [...retained, ...durable]
    restoreSkills(immediate)
    restoreCombinedInput([current, ...immediate])
    options.pendingAttachments.value = [...options.pendingAttachments.value, ...queuedAttachments]
    options.pendingSessionIntent.value = options.pendingSessionIntent.value || headIntent || null
    options.autoResizeTextarea()
    options.resetInputHistory()
    let stillOwnsComposer = composerOwnershipGuard()
    for (const item of durable) {
      void cancelForComposer(item, () => stillOwnsComposer(), () => {
        restoreSkills([item])
        restoreCombinedInput([currentComposerInput(), item])
        options.pendingAttachments.value = [
          ...options.pendingAttachments.value,
          ...(item.attachments || []),
        ]
        options.pendingSessionIntent.value = (
          options.pendingSessionIntent.value || item.intent || null
        )
        options.autoResizeTextarea()
        options.resetInputHistory()
        stillOwnsComposer = composerOwnershipGuard()
      })
    }
    return true
  }

  function drainQueueHead() {
    clearPendingDrainAfterTerminalTimer()
    if (pendingQueue.value.length === 0 || queuePolicy.read(queueScope()).paused) return
    const head = pendingQueue.value[0]
    if (head?.retiredAnnotationInput || head?.pendingRetainAfterCancel === true) return
    const ownerSessionKey = head?.ownerSessionKey || options.sessionKey.value
    if (ownerSessionKey !== options.sessionKey.value) {
      if (head) head.deliveryState = 'retryable'
      return
    }
    if (options.dispatchPendingItem) {
      const preDispatchGuard = captureFollowupGuard(ownerSessionKey)
      const item = beginPendingDelivery(head.pendingUiId)
      if (!item) return
      nextTick(() => {
        void (async () => {
          let outcome: PendingDeliveryOutcome = 'retryable_failure'
          try {
            if (preDispatchGuard()) {
              outcome = await options.dispatchPendingItem!(item, ownerSessionKey, preDispatchGuard)
            } else {
              outcome = 'deferred'
            }
          } catch {
            // Keep the queue item as an explicit idempotent retry. The send
            // layer normally converts transport errors to this outcome, but
            // the queue must also fail closed if an unexpected error escapes.
            outcome = 'retryable_failure'
          } finally {
            settlePendingDelivery(item, outcome)
          }
        })()
      })
      return
    }
    // The legacy composer callback cannot retain an offline item's delivery
    // identity. Such drafts require the guarded pending-item dispatch port.
    if (!head || head.pendingDeliveryIdentity) return
    head.deliveryState = 'steering'
    const preDispatchGuard = captureFollowupGuard(ownerSessionKey)
    nextTick(() => {
      if (!preDispatchGuard()) {
        delete head.deliveryState
        return
      }
      if (
        options.sessionKey.value !== ownerSessionKey
        || pendingQueue.value[0] !== head
      ) return
      pendingQueue.value.shift()
      if (options.selectedSkills) options.selectedSkills.value = copySelectedSkills(head.selectedSkills)
      restoreInput(head.text || '', head.localPathReferences)
      options.pendingAttachments.value = head.attachments || []
      options.pendingSessionIntent.value = head.intent || null
      options.sendCurrentInput()
    })
  }

  function schedulePendingDrainAfterTerminal() {
    if (queuePolicy.read(queueScope()).paused) return
    if (pendingQueue.value.length === 0) {
      // A terminal subscription replay can arrive while response handoff is
      // still hydrating, before the matching follow-up reaches the queue.
      // Preserve that terminal signal until the blocker releases.
      deferredDrainRequested = options.isBlocked()
      return
    }
    deferredDrainRequested = true
    if (hasDeliveryBarrier.value || isReordering.value) return
    armPendingDrainTimer()
  }

  function armPendingDrainTimer() {
    cancelPendingDrainTimer()
    if (hasDeliveryBarrier.value || isReordering.value) return
    pendingDrainTimer = setTimeout(() => {
      pendingDrainTimer = null
      if (pendingQueue.value.length === 0) {
        deferredDrainRequested = false
        return
      }
      if (
        options.isStreaming.value
        || queuePolicy.read(queueScope()).paused
        || options.isBlocked()
        || hasDeliveryBarrier.value
        || isReordering.value
      ) return
      deferredDrainRequested = false
      drainQueueHead()
    }, 50)
  }

  function flushDeferredPendingDrain() {
    if (
      !deferredDrainRequested
      || queuePolicy.read(queueScope()).paused
      || pendingQueue.value.length === 0
      || hasDeliveryBarrier.value
      || isReordering.value
    ) return
    armPendingDrainTimer()
  }

  function pendingReorderMode(): PendingReorderMode | null {
    if (
      pendingQueue.value.length < 2
      || pendingQueue.value.some(item => (
        !ordinaryDurableItem(item)
        || !identityAllowsDelivery(item)
        || Boolean(item.ownerRequestId)
        || !Number.isSafeInteger(item.pendingWalRevision)
        || item.pendingPersistenceState === 'saving'
        || item.pendingPersistenceState === 'retryable'
        || item.pendingPersistenceState === 'cancelling'
      ))
    ) return null
    if (
      pendingQueue.value.every(item => (
        item.pendingPersistenceState === 'local_only'
        && item.pendingMayHaveServerCopy === false
      ))
      && options.pendingInputWal?.commitOrder
    ) return 'local'
    if (
      pendingQueue.value.every(item => (
        item.pendingPersistenceState === 'staged'
        && Number.isSafeInteger(item.pendingServerRevision)
      ))
      && supportsServerReorder()
    ) return 'server'
    return null
  }

  function canReorderPendingQueue(): boolean {
    return pendingReorderMode() !== null
  }

  function reorderContainer(snapshot: PendingReorderSnapshot): ChatPendingItem[] {
    return snapshot.sessionKey === options.sessionKey.value
      ? pendingQueue.value
      : parkedQueues.get(snapshot.sessionKey) || []
  }

  function reorderItems(snapshot: PendingReorderSnapshot): ChatPendingItem[] {
    const ids = new Set(snapshot.originalOrder)
    return reorderContainer(snapshot).filter(item => ids.has(item.pendingInputId || ''))
  }

  function ownsReorder(snapshot: PendingReorderSnapshot): boolean {
    return !disposed && pendingReorders.get(reorderOwnerKey(snapshot.sessionKey, snapshot.deliveryIdentity)) === snapshot
  }

  function canApplyServerReorder(snapshot: PendingReorderSnapshot): boolean {
    return ownsReorder(snapshot) && snapshot.deliveryIdentity === (options.deliveryIdentity?.value ?? null)
  }

  function restorePendingOrder(snapshot: PendingReorderSnapshot, orderedIds: string[]) {
    const queue = reorderItems(snapshot)
    const byId = new Map(
      queue.map(item => [item.pendingInputId || '', item]),
    )
    if (orderedIds.some(id => !byId.has(id))) return
    const container = reorderContainer(snapshot)
    let next = 0
    // A different delivery identity may have hydrated its own rows while this
    // owner was hidden. Reorder only the captured rows, retaining every other row.
    for (let index = 0; index < container.length; index++) {
      if (byId.has(container[index]!.pendingInputId || '')) container[index] = byId.get(orderedIds[next++]!)!
    }
  }

  function finishPendingReorder(snapshot: PendingReorderSnapshot) {
    if (!ownsReorder(snapshot)) return
    pendingReorders.delete(reorderOwnerKey(snapshot.sessionKey, snapshot.deliveryIdentity))
    if (snapshot.sessionKey === options.sessionKey.value
      && snapshot.deliveryIdentity === (options.deliveryIdentity?.value ?? null)) {
      if (snapshot.deferredHydrate) void hydratePendingQueue(snapshot.sessionKey)
      flushDeferredPendingDrain()
    }
    parkedQueues.trim()
  }

  async function applyServerReorderItems(
    snapshot: PendingReorderSnapshot,
    items: PendingInputServerItem[],
  ): Promise<void> {
    if (!canApplyServerReorder(snapshot)) return
    const queue = reorderItems(snapshot)
    const byId = new Map(
      items.map(item => [item.pendingInputId, item]),
    )
    const orderedIds = items
      .slice()
      .sort((left, right) => Number(left.position) - Number(right.position))
      .map(item => item.pendingInputId)
    if (
      orderedIds.length !== queue.length
      || new Set(orderedIds).size !== orderedIds.length
      || queue.some(item => !byId.has(item.pendingInputId || ''))
    ) throw new Error('Gateway returned an incomplete pending order')
    restorePendingOrder(snapshot, orderedIds)
    for (const item of queue) {
      const serverItem = byId.get(item.pendingInputId || '')!
      item.pendingPosition = Number(serverItem.position)
      item.pendingServerRevision = Number(serverItem.revision)
      item.pendingWalRevision = (item.pendingWalRevision ?? 0) + 1
    }
    const cacheCommits = queue.map(item => ({
      item, snapshot: parkedQueues.snapshotForCommit(item),
    }))
    if (!options.pendingInputWal?.putMany) {
      for (const item of queue) {
        await options.pendingInputWal?.put(walRecordForItem(item, 'staged'))
      }
    } else {
      await options.pendingInputWal.putMany(
        queue.map(item => walRecordForItem(item, 'staged')),
      )
    }
    if (options.pendingInputWal) {
      for (const commit of cacheCommits) parkedQueues.rememberCommitted(commit.item, commit.snapshot)
    }
  }

  async function recoverServerReorder(snapshot: PendingReorderSnapshot): Promise<boolean> {
    if (!pendingInputQueue || !supportsServerQueue() || !canApplyServerReorder(snapshot)) return false
    const expectedOrder = reorderItems(snapshot).map(item => item.pendingInputId)
    try {
      const response = { items: await pendingInputQueue.list(snapshot.sessionKey) }
      if (!canApplyServerReorder(snapshot)) return false
      const items = Array.isArray(response.items) ? response.items : []
      const serverOrder = items
        .slice()
        .sort((left, right) => Number(left.position) - Number(right.position))
        .map(item => item.pendingInputId)
      await applyServerReorderItems(snapshot, items)
      if (!canApplyServerReorder(snapshot)) return false
      if (serverOrder.some((id, index) => id !== expectedOrder[index])) {
        options.onPendingPersistenceError?.('order_conflict')
      }
      broadcastChange(snapshot.sessionKey)
      return true
    } catch {
      return false
    }
  }

  function beginPendingReorder(index: number): boolean {
    if (
      isReordering.value
      || !canReorderPendingQueue()
      || !pendingQueue.value[index]
    ) return false
    cancelPendingDrainTimer()
    // A list/WAL read admitted before the drag cannot overwrite the newly
    // captured order or revisions while its transaction is committing.
    hydrateGeneration += 1
    const mode = pendingReorderMode()!
    pendingReorders.set(reorderOwnerKey(options.sessionKey.value), {
      sessionKey: options.sessionKey.value,
      deliveryIdentity: options.deliveryIdentity?.value ?? null,
      mode,
      originalOrder: pendingQueue.value.map(item => item.pendingInputId!),
      expectedWalRevisions: Object.fromEntries(
        pendingQueue.value.map(item => [item.pendingInputId!, item.pendingWalRevision!]),
      ),
    })
    return true
  }

  function reorderPendingItem(fromIndex: number, toIndex: number): boolean {
    if (
      !isReordering.value
      || activeReorder()?.started
      || fromIndex === toIndex
      || fromIndex < 0
      || toIndex < 0
      || fromIndex >= pendingQueue.value.length
      || toIndex >= pendingQueue.value.length
    ) return false
    const [item] = pendingQueue.value.splice(fromIndex, 1)
    if (!item) return false
    pendingQueue.value.splice(toIndex, 0, item)
    return true
  }

  async function commitPendingReorder(snapshot: PendingReorderSnapshot) {
    if (!ownsReorder(snapshot)) return
    const queue = reorderItems(snapshot)
    const orderedIds = queue.map(item => item.pendingInputId!)
    if (orderedIds.every((id, index) => id === snapshot.originalOrder[index])) {
      finishPendingReorder(snapshot)
      return
    }
    if (snapshot.mode === 'local') {
      try {
        const result = await options.pendingInputWal!.commitOrder!(
          snapshot.sessionKey,
          orderedIds,
          snapshot.expectedWalRevisions,
        )
        if (!ownsReorder(snapshot)) return
        const byId = new Map(result.records.map(record => [record.pendingInputId, record]))
        for (const item of queue) {
          const record = byId.get(item.pendingInputId!)!
          item.pendingPosition = record.position
          item.pendingWalRevision = record.walRevision
          parkedQueues.rememberCommitted(item, parkedQueues.snapshotForCommit(item))
        }
        broadcastChange(snapshot.sessionKey)
      } catch {
        if (!ownsReorder(snapshot)) return
        // Keep the original owner for reconciliation. If it is hidden, the
        // next visit hydrates the original queue from its authoritative WAL.
        snapshot.deferredHydrate = true
        finishPendingReorder(snapshot)
        options.onPendingPersistenceError?.('wal_failed')
        return
      }
      finishPendingReorder(snapshot)
      return
    }
    try {
      const response = await pendingInputQueue!.reorder({
          key: snapshot.sessionKey,
          items: queue.map(item => ({
            pendingInputId: item.pendingInputId,
            expectedRevision: item.pendingServerRevision,
          })),
        })
      if (!canApplyServerReorder(snapshot)) return
      await applyServerReorderItems(snapshot, Array.isArray(response.items) ? response.items : [])
      if (!canApplyServerReorder(snapshot)) return
      broadcastChange(snapshot.sessionKey)
      finishPendingReorder(snapshot)
    } catch {
      // An unknown RPC result may have committed. Keep the delivery barrier
      // until an authoritative list proves which order won.
      if (await recoverServerReorder(snapshot)) finishPendingReorder(snapshot)
      else if (canApplyServerReorder(snapshot)) options.onPendingPersistenceError?.('server_rejected')
    }
  }

  function endPendingReorder(): Promise<void> {
    const snapshot = activeReorder()
    if (!snapshot) return Promise.resolve()
    if (snapshot.commit) return snapshot.commit
    snapshot.started = true
    snapshot.commit = commitPendingReorder(snapshot).finally(() => {
      snapshot.commit = undefined
    })
    return snapshot.commit
  }

  function cancelPendingReorder() {
    const snapshot = activeReorder()
    if (!snapshot || snapshot.started) return
    restorePendingOrder(snapshot, snapshot.originalOrder)
    finishPendingReorder(snapshot)
  }

  function cancelPendingDrainTimer() {
    if (pendingDrainTimer) {
      clearTimeout(pendingDrainTimer)
      pendingDrainTimer = null
    }
  }

  function clearPendingDrainAfterTerminalTimer() {
    cancelPendingDrainTimer()
    deferredDrainRequested = false
  }

  function cleanup() {
    cancelPendingReorder()
    disposed = true
    pendingReorders.clear()
    hydrateGeneration += 1
    clearPendingDrainAfterTerminalTimer()
    parkedQueues.dispose()
    broadcast?.close()
    if (typeof window !== 'undefined') window.removeEventListener('storage', policyStorageListener)
    options.pendingInputWal?.close()
  }

  return {
    pendingQueue,
    autoSendPaused,
    canSendFollowup,
    pausePendingAutoSend,
    resumePendingAutoSend,
    capturePendingAutoSendResume,
    captureFollowupGuard,
    getParkedQueueUsage: () => parkedQueues.usage(),
    canQueueMore,
    canReorder,
    busySendMode,
    isReordering,
    maxPending: MAX_PENDING,
    enqueuePendingPayload,
    restoreQueuedAnnotations,
    enqueuePendingInput,
    enqueuePendingSteerAttempt,
    removePendingChip,
    beginPendingDelivery,
    settlePendingDelivery,
    cancelDurableItem,
    clearPendingQueue,
    switchPendingQueue,
    adoptPendingQueue,
    recoverPendingQueueHandoff,
    failPendingQueueHandoff,
    editPendingItem,
    popPendingTail,
    popAllPendingIntoComposer,
    beginPendingReorder,
    reorderPendingItem,
    endPendingReorder,
    schedulePendingDrainAfterTerminal,
    flushDeferredPendingDrain,
    hydratePendingQueue,
    clearPendingDrainAfterTerminalTimer,
    cleanup,
  }
}
